INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000000001', '50000000-0000-0000-0000-000000000001', 'simple', 'mcq', 'What is React primarily used for?', '["Backend APIs", "Building user interfaces", "Database management", "Mobile apps only"]', 'Building user interfaces', 'React is a JavaScript library for building user interfaces, particularly for single-page applications.', 'active'),
('60000000-0000-0000-0000-000000000002', '50000000-0000-0000-0000-000000000001', 'simple', 'mcq', 'Which method is called when a component is first mounted?', '["componentWillMount", "componentDidMount", "componentMounted", "render"]', 'componentDidMount', 'componentDidMount is a lifecycle method invoked immediately after a component is mounted (inserted into the tree).', 'active'),
('60000000-0000-0000-0000-000000000003', '50000000-0000-0000-0000-000000000001', 'simple', 'mcq', 'What does JSX stand for?', '["JavaScript XML", "Java Syntax Extension", "JavaScript Extension", "JS XML"]', 'JavaScript XML', 'JSX stands for JavaScript XML, which is a syntax extension for JavaScript that allows writing HTML-like code in React.', 'active'),
('60000000-0000-0000-0000-000000000004', '50000000-0000-0000-0000-000000000001', 'simple', 'code_mcq', 'How do you create a React element using JSX?', '["<h1>Hello</h1>", "React.createElement(''h1'')", "new React.Element()", "document.createElement(''h1'')"]', '<h1>Hello</h1>', 'JSX allows you to write HTML-like code which is then transpiled to React.createElement.', 'active'),
('60000000-0000-0000-0000-000000000005', '50000000-0000-0000-0000-000000000001', 'intermediate', 'mcq', 'What is the purpose of keys in React lists?', '["Improve performance", "Add styling", "Enable state updates", "Handle events"]', 'Improve performance', 'Keys help React identify which items have changed, are added, or are removed, improving reconciliation performance.', 'active'),
('60000000-0000-0000-0000-000000000006', '50000000-0000-0000-0000-000000000001', 'intermediate', 'mcq', 'Which hook replaces componentDidUpdate?', '["useEffect", "useState", "useMemo", "useCallback"]', 'useEffect', 'useEffect with dependencies can mimic componentDidUpdate behavior in functional components.', 'active'),
('60000000-0000-0000-0000-000000000007', '50000000-0000-0000-0000-000000000001', 'intermediate', 'mcq', 'What is prop drilling?', '["Passing props through multiple levels", "Validating props", "Setting default props", "Prop mutation"]', 'Passing props through multiple levels', 'Prop drilling refers to passing props through multiple intermediate components to reach a deeply nested component.', 'active'),
('60000000-0000-0000-0000-000000000008', '50000000-0000-0000-0000-000000000001', 'intermediate', 'code_mcq', 'What does this code do? const [count, setCount] = useState(0);', '["Creates a state variable", "Creates a ref", "Creates an effect", "Creates a context"]', 'Creates a state variable', 'useState hook creates a state variable (count) and a function to update it (setCount), initialized to 0.', 'active'),
('60000000-0000-0000-0000-000000000009', '50000000-0000-0000-0000-000000000001', 'expert', 'mcq', 'What is the Virtual DOM?', '["A lightweight copy of the real DOM", "A browser API", "A CSS framework", "A state management tool"]', 'A lightweight copy of the real DOM', 'Virtual DOM is a programming concept where an ideal, or "virtual", representation of the UI is kept in memory.', 'active'),
('60000000-0000-0000-0000-000000000010', '50000000-0000-0000-0000-000000000001', 'expert', 'mcq', 'When should you use useMemo?', '["To memoize expensive calculations", "To handle side effects", "To manage context", "To create refs"]', 'To memoize expensive calculations', 'useMemo memoizes expensive calculations, recomputing only when dependencies change.', 'active'),
('60000000-0000-0000-0000-000000000011', '50000000-0000-0000-0000-000000000001', 'expert', 'code_mcq', 'What problem does this pattern solve? const ThemeContext = React.createContext();', '["Prop drilling", "Component reusability", "State management", "All of the above"]', 'Prop drilling', 'Context API helps avoid prop drilling by providing a way to pass data through the component tree without passing props manually.', 'active'),
('60000000-0000-0000-0000-000000000012', '50000000-0000-0000-0000-000000000001', 'expert', 'mcq', 'What is reconciliation in React?', '["The diffing algorithm", "State synchronization", "Prop validation", "Error handling"]', 'The diffing algorithm', 'Reconciliation is React''s diffing algorithm that determines what changed in the Virtual DOM to update the actual DOM.', 'active'),
('60000000-0000-0000-0000-000000000013', '50000000-0000-0000-0000-000000000001', 'expert', 'mcq', 'Which lifecycle method is unsafe for side effects?', '["componentWillMount", "componentDidMount", "shouldComponentUpdate", "componentWillUnmount"]', 'componentWillMount', 'componentWillMount is deprecated and unsafe for side effects; use componentDidMount instead.', 'active')
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000000014', '50000000-0000-0000-0000-000000000002', 'simple', 'mcq', 'What is a Higher-Order Component (HOC)?', '["A component that takes a component and returns a new component", "A base component", "A hook", "A context provider"]', 'A component that takes a component and returns a new component', 'HOCs are functions that take a component and return a new component with additional props or behavior.', 'active'),
('60000000-0000-0000-0000-000000000015', '50000000-0000-0000-0000-000000000002', 'simple', 'mcq', 'What is React Router used for?', '["Client-side routing", "API routing", "Database routing", "Server routing"]', 'Client-side routing', 'React Router enables client-side routing in React applications.', 'active'),
('60000000-0000-0000-0000-000000000016', '50000000-0000-0000-0000-000000000002', 'simple', 'mcq', 'What does Redux help with?', '["State management", "Routing", "Styling", "Testing"]', 'State management', 'Redux is a predictable state container for JavaScript apps, commonly used with React.', 'active'),
('60000000-0000-0000-0000-000000000017', '50000000-0000-0000-0000-000000000002', 'simple', 'code_mcq', 'What does this return? React.memo(MyComponent)', '["A memoized component", "A stateful component", "An error", "A hook"]', 'A memoized component', 'React.memo is a higher-order component that memoizes the result, preventing re-renders if props haven''t changed.', 'active'),
('60000000-0000-0000-0000-000000000018', '50000000-0000-0000-0000-000000000002', 'intermediate', 'mcq', 'What is the purpose of useCallback?', '["Memoize functions", "Memoize values", "Handle side effects", "Manage state"]', 'Memoize functions', 'useCallback returns a memoized version of a callback function that only changes if dependencies change.', 'active'),
('60000000-0000-0000-0000-000000000019', '50000000-0000-0000-0000-000000000002', 'intermediate', 'mcq', 'What is code splitting?', '["Splitting code into smaller bundles", "Dividing components", "Separating CSS", "Splitting state"]', 'Splitting code into smaller bundles', 'Code splitting allows splitting code into smaller bundles that can be loaded on demand.', 'active'),
('60000000-0000-0000-0000-000000000020', '50000000-0000-0000-0000-000000000002', 'intermediate', 'mcq', 'What is server-side rendering (SSR)?', '["Rendering React on the server", "Rendering on CDN", "Client rendering", "Static generation"]', 'Rendering React on the server', 'SSR renders React components on the server and sends HTML to the client.', 'active'),
('60000000-0000-0000-0000-000000000021', '50000000-0000-0000-0000-000000000002', 'intermediate', 'code_mcq', 'What pattern is this? const { data, error } = useSWR(''/api/user'');', '["Data fetching", "State management", "Event handling", "Form validation"]', 'Data fetching', 'This shows the useSWR hook pattern for data fetching with caching and revalidation.', 'active'),
('60000000-0000-0000-0000-000000000022', '50000000-0000-0000-0000-000000000002', 'expert', 'mcq', 'What is concurrent mode?', '["A set of features for responsive apps", "A rendering mode", "A state management", "A testing strategy"]', 'A set of features for responsive apps', 'Concurrent mode helps apps stay responsive by rendering without blocking the main thread.', 'active'),
('60000000-0000-0000-0000-000000000023', '50000000-0000-0000-0000-000000000002', 'expert', 'mcq', 'What are error boundaries?', '["Components that catch JavaScript errors", "Error handling functions", "try-catch blocks", "Debug tools"]', 'Components that catch JavaScript errors', 'Error boundaries are React components that catch JavaScript errors anywhere in their child component tree.', 'active'),
('60000000-0000-0000-0000-000000000024', '50000000-0000-0000-0000-000000000002', 'expert', 'code_mcq', 'What does React.lazy() enable?', '["Code splitting", "Lazy loading", "Both A and B", "Neither"]', 'Both A and B', 'React.lazy() enables code splitting and lazy loading of components.', 'active'),
('60000000-0000-0000-0000-000000000025', '50000000-0000-0000-0000-000000000002', 'expert', 'mcq', 'What is the purpose of useTransition?', '["Mark state updates as non-urgent", "Handle animations", "Manage transitions", "Control rendering"]', 'Mark state updates as non-urgent', 'useTransition marks state updates as non-urgent, allowing interruptions for more urgent updates.', 'active'),
('60000000-0000-0000-0000-000000000026', '50000000-0000-0000-0000-000000000002', 'expert', 'mcq', 'What is React Server Components?', '["Components that render on the server", "Client components", "Hybrid components", "Legacy components"]', 'Components that render on the server', 'React Server Components allow rendering components on the server to reduce bundle size.', 'active')
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000000027', '50000000-0000-0000-0000-000000000003', 'simple', 'mcq', 'What is Node.js?', '["JavaScript runtime", "Web framework", "Database", "Browser"]', 'JavaScript runtime', 'Node.js is a JavaScript runtime built on Chrome''s V8 JavaScript engine.', 'active'),
('60000000-0000-0000-0000-000000000028', '50000000-0000-0000-0000-000000000003', 'simple', 'mcq', 'Which module is built-in for file operations?', '["fs", "http", "path", "url"]', 'fs', 'The fs module provides an API for interacting with the file system.', 'active'),
('60000000-0000-0000-0000-000000000029', '50000000-0000-0000-0000-000000000003', 'simple', 'mcq', 'What does require() do?', '["Imports modules", "Exports modules", "Requires permissions", "Checks existence"]', 'Imports modules', 'require() is used to import modules in CommonJS.', 'active'),
('60000000-0000-0000-0000-000000000030', '50000000-0000-0000-0000-000000000003', 'simple', 'code_mcq', 'What does process.argv contain?', '["Command-line arguments", "Environment variables", "Process ID", "Current directory"]', 'Command-line arguments', 'process.argv returns an array containing the command-line arguments.', 'active'),
('60000000-0000-0000-0000-000000000031', '50000000-0000-0000-0000-000000000003', 'intermediate', 'mcq', 'What is the event loop?', '["Mechanism that handles async operations", "Event handler", "Loop construct", "Timer"]', 'Mechanism that handles async operations', 'The event loop is what allows Node.js to perform non-blocking I/O operations.', 'active'),
('60000000-0000-0000-0000-000000000032', '50000000-0000-0000-0000-000000000003', 'intermediate', 'mcq', 'What is libuv?', '["Multiplatform C library", "JavaScript library", "Package manager", "Testing framework"]', 'Multiplatform C library', 'libuv is a multi-platform C library that provides support for asynchronous I/O.', 'active'),
('60000000-0000-0000-0000-000000000033', '50000000-0000-0000-0000-000000000003', 'intermediate', 'mcq', 'What does setImmediate() do?', '["Executes after I/O callbacks", "Executes immediately", "Sets timeout", "Clears queue"]', 'Executes after I/O callbacks', 'setImmediate() schedules a callback to be executed after I/O callbacks.', 'active'),
('60000000-0000-0000-0000-000000000034', '50000000-0000-0000-0000-000000000003', 'intermediate', 'code_mcq', 'What is this pattern? const { spawn } = require(''child_process'');', '["Spawning child processes", "Creating threads", "Forking processes", "Clustering"]', 'Spawning child processes', 'This shows how to spawn child processes in Node.js using the child_process module.', 'active'),
('60000000-0000-0000-0000-000000000035', '50000000-0000-0000-0000-000000000003', 'expert', 'mcq', 'What is the difference between require() and import?', '["Synchronous vs asynchronous", "CommonJS vs ES6", "Both A and B", "Neither"]', 'Both A and B', 'require() is synchronous CommonJS, while import is asynchronous ES6 modules.', 'active'),
('60000000-0000-0000-0000-000000000036', '50000000-0000-0000-0000-000000000003', 'expert', 'mcq', 'What are worker threads?', '["Run JavaScript in parallel", "Child processes", "Web workers", "Thread pool"]', 'Run JavaScript in parallel', 'Worker threads allow running JavaScript in parallel using separate threads.', 'active'),
('60000000-0000-0000-0000-000000000037', '50000000-0000-0000-0000-000000000003', 'expert', 'mcq', 'What is the purpose of --inspect flag?', '["Enable debugger", "Inspect modules", "Check memory", "Profile CPU"]', 'Enable debugger', '--inspect enables the Node.js debugger protocol.', 'active'),
('60000000-0000-0000-0000-000000000038', '50000000-0000-0000-0000-000000000003', 'expert', 'code_mcq', 'What does Buffer.alloc(10) create?', '["10-byte buffer", "10-character string", "10-element array", "10MB memory"]', '10-byte buffer', 'Buffer.alloc() creates a new buffer of the specified size.', 'active'),
('60000000-0000-0000-0000-000000000039', '50000000-0000-0000-0000-000000000003', 'expert', 'mcq', 'What is the module wrapper function?', '["Wraps module code", "Exports wrapper", "Require function", "Import wrapper"]', 'Wraps module code', 'Node.js wraps module code in a function for isolation.', 'active')
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000000040', '50000000-0000-0000-0000-000000000004', 'simple', 'mcq', 'What is Express.js?', '["Web framework for Node.js", "Template engine", "Database ORM", "Testing framework"]', 'Web framework for Node.js', 'Express is a minimal and flexible Node.js web application framework.', 'active'),
('60000000-0000-0000-0000-000000000041', '50000000-0000-0000-0000-000000000004', 'simple', 'mcq', 'What does app.use() do?', '["Mounts middleware", "Defines routes", "Starts server", "Configures views"]', 'Mounts middleware', 'app.use() mounts middleware functions at the specified path.', 'active'),
('60000000-0000-0000-0000-000000000042', '50000000-0000-0000-0000-000000000004', 'simple', 'mcq', 'How do you define a GET route?', '["app.get()", "app.route()", "app.GET()", "app.use()"]', 'app.get()', 'app.get() defines a route for handling GET requests.', 'active'),
('60000000-0000-0000-0000-000000000043', '50000000-0000-0000-0000-000000000004', 'simple', 'code_mcq', 'What does this return? res.json({ success: true })', '["JSON response", "HTML response", "Text response", "File response"]', 'JSON response', 'res.json() sends a JSON response with proper Content-Type header.', 'active'),
('60000000-0000-0000-0000-000000000044', '50000000-0000-0000-0000-000000000004', 'intermediate', 'mcq', 'What is middleware in Express?', '["Functions that have access to req, res, and next", "Route handlers", "Error handlers", "Template engines"]', 'Functions that have access to req, res, and next', 'Middleware functions can execute code, modify req/res objects, and call next().', 'active'),
('60000000-0000-0000-0000-000000000045', '50000000-0000-0000-0000-000000000004', 'intermediate', 'mcq', 'What is CORS middleware for?', '["Handle cross-origin requests", "Compress responses", "Parse cookies", "Log requests"]', 'Handle cross-origin requests', 'CORS middleware enables Cross-Origin Resource Sharing.', 'active'),
('60000000-0000-0000-0000-000000000046', '50000000-0000-0000-0000-000000000004', 'intermediate', 'mcq', 'What is the purpose of helmet.js?', '["Security headers", "Compression", "Rate limiting", "Validation"]', 'Security headers', 'helmet.js helps secure Express apps by setting various HTTP headers.', 'active'),
('60000000-0000-0000-0000-000000000047', '50000000-0000-0000-0000-000000000004', 'intermediate', 'code_mcq', 'What does this handle? app.use((err, req, res, next) => {...})', '["Error handling middleware", "Route middleware", "Authentication", "Validation"]', 'Error handling middleware', 'Four-parameter functions are error-handling middleware in Express.', 'active'),
('60000000-0000-0000-0000-000000000048', '50000000-0000-0000-0000-000000000004', 'expert', 'mcq', 'What is the purpose of express.Router()?', '["Create modular route handlers", "Handle errors", "Configure middleware", "Start server"]', 'Create modular route handlers', 'express.Router() creates modular, mountable route handlers.', 'active'),
('60000000-0000-0000-0000-000000000049', '50000000-0000-0000-0000-000000000004', 'expert', 'mcq', 'What is JWT used for?', '["Authentication", "Authorization", "Both A and B", "Neither"]', 'Both A and B', 'JWTs are used for both authentication and authorization.', 'active'),
('60000000-0000-0000-0000-000000000050', '50000000-0000-0000-0000-000000000004', 'expert', 'mcq', 'What is rate limiting?', '["Limit requests from an IP", "Limit bandwidth", "Limit connections", "Limit memory"]', 'Limit requests from an IP', 'Rate limiting controls how many requests a client can make in a given time.', 'active'),
('60000000-0000-0000-0000-000000000051', '50000000-0000-0000-0000-000000000004', 'expert', 'code_mcq', 'What pattern is this? const pool = new Pool({ connectionString });', '["Connection pooling", "Singleton pattern", "Factory pattern", "Observer pattern"]', 'Connection pooling', 'This shows database connection pooling with node-postgres.', 'active'),
('60000000-0000-0000-0000-000000000052', '50000000-0000-0000-0000-000000000004', 'expert', 'mcq', 'What is the purpose of express.static()?', '["Serve static files", "Handle dynamic routes", "Parse form data", "Set cookies"]', 'Serve static files', 'express.static() serves static files like images, CSS, JavaScript.', 'active')
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000000053', '50000000-0000-0000-0000-000000000005', 'simple', 'mcq', 'What type of database is MongoDB?', '["NoSQL", "SQL", "Graph", "Key-value"]', 'NoSQL', 'MongoDB is a document-based NoSQL database.', 'active'),
('60000000-0000-0000-0000-000000000054', '50000000-0000-0000-0000-000000000005', 'simple', 'mcq', 'What is a collection in MongoDB?', '["Group of documents", "Table", "Schema", "Database"]', 'Group of documents', 'A collection is equivalent to a table in SQL, containing documents.', 'active'),
('60000000-0000-0000-0000-000000000055', '50000000-0000-0000-0000-000000000005', 'simple', 'mcq', 'What is a document in MongoDB?', '["BSON object", "JSON object", "XML object", "CSV row"]', 'BSON object', 'Documents are stored as BSON (Binary JSON) objects.', 'active'),
('60000000-0000-0000-0000-000000000056', '50000000-0000-0000-0000-000000000005', 'simple', 'code_mcq', 'What does db.collection.find() return?', '["Cursor to documents", "Array of documents", "Single document", "Count"]', 'Cursor to documents', 'find() returns a cursor that can be iterated to access documents.', 'active'),
('60000000-0000-0000-0000-000000000057', '50000000-0000-0000-0000-000000000005', 'intermediate', 'mcq', 'What is the purpose of indexes in MongoDB?', '["Improve query performance", "Enforce uniqueness", "Both A and B", "Neither"]', 'Both A and B', 'Indexes improve query performance and can enforce uniqueness constraints.', 'active'),
('60000000-0000-0000-0000-000000000058', '50000000-0000-0000-0000-000000000005', 'intermediate', 'mcq', 'What is aggregation in MongoDB?', '["Data processing pipeline", "Data migration", "Backup process", "Replication"]', 'Data processing pipeline', 'Aggregation processes data records and returns computed results.', 'active'),
('60000000-0000-0000-0000-000000000059', '50000000-0000-0000-0000-000000000005', 'intermediate', 'mcq', 'What is sharding?', '["Horizontal partitioning", "Vertical partitioning", "Replication", "Backup"]', 'Horizontal partitioning', 'Sharding distributes data across multiple machines.', 'active'),
('60000000-0000-0000-0000-000000000060', '50000000-0000-0000-0000-000000000005', 'intermediate', 'code_mcq', 'What does this update? db.users.updateOne({age: {$gt: 18}}, {$set: {adult: true}})', '["Updates first matching document", "Updates all documents", "Inserts document", "Deletes document"]', 'Updates first matching document', 'updateOne() updates the first document that matches the filter.', 'active'),
('60000000-0000-0000-0000-000000000061', '50000000-0000-0000-0000-000000000005', 'expert', 'mcq', 'What is a replica set?', '["Group of mongod instances", "Backup set", "Shard set", "Index set"]', 'Group of mongod instances', 'A replica set provides redundancy and high availability.', 'active'),
('60000000-0000-0000-0000-000000000062', '50000000-0000-0000-0000-000000000005', 'expert', 'mcq', 'What is the oplog?', '["Operations log", "Optimization log", "Output log", "Object log"]', 'Operations log', 'The oplog records all operations that modify data.', 'active'),
('60000000-0000-0000-0000-000000000063', '50000000-0000-0000-0000-000000000005', 'expert', 'mcq', 'What is MongoDB Atlas?', '["Cloud database service", "Desktop client", "CLI tool", "ORM"]', 'Cloud database service', 'MongoDB Atlas is a fully-managed cloud database service.', 'active'),
('60000000-0000-0000-0000-000000000064', '50000000-0000-0000-0000-000000000005', 'expert', 'code_mcq', 'What does $lookup stage do in aggregation?', '["Performs left outer join", "Filters documents", "Groups documents", "Sorts documents"]', 'Performs left outer join', '$lookup performs a left outer join between collections.', 'active'),
('60000000-0000-0000-0000-000000000065', '50000000-0000-0000-0000-000000000005', 'expert', 'mcq', 'What is change streams?', '["Real-time data changes", "Stream processing", "Data migration", "Backup streams"]', 'Real-time data changes', 'Change streams allow applications to access real-time data changes.', 'active')
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000000066', '50000000-0000-0000-0000-000000000006', 'simple', 'mcq', 'What type of database is PostgreSQL?', '["Relational", "NoSQL", "Document", "Graph"]', 'Relational', 'PostgreSQL is a powerful, open-source relational database.', 'active'),
('60000000-0000-0000-0000-000000000067', '50000000-0000-0000-0000-000000000006', 'simple', 'mcq', 'What is a primary key?', '["Unique identifier for a row", "Foreign key", "Index", "Constraint"]', 'Unique identifier for a row', 'A primary key uniquely identifies each row in a table.', 'active'),
('60000000-0000-0000-0000-000000000068', '50000000-0000-0000-0000-000000000006', 'simple', 'mcq', 'What does SQL stand for?', '["Structured Query Language", "Simple Query Language", "Standard Query Language", "System Query Language"]', 'Structured Query Language', 'SQL is the standard language for relational databases.', 'active'),
('60000000-0000-0000-0000-000000000069', '50000000-0000-0000-0000-000000000006', 'simple', 'code_mcq', 'What does SELECT * FROM users WHERE age > 18; return?', '["All users over 18", "First user over 18", "Count of users", "Users table"]', 'All users over 18', 'This query returns all rows where age is greater than 18.', 'active'),
('60000000-0000-0000-0000-000000000070', '50000000-0000-0000-0000-000000000006', 'intermediate', 'mcq', 'What is a JOIN used for?', '["Combine rows from multiple tables", "Filter rows", "Sort rows", "Group rows"]', 'Combine rows from multiple tables', 'JOIN combines columns from one or more tables.', 'active'),
('60000000-0000-0000-0000-000000000071', '50000000-0000-0000-0000-000000000006', 'intermediate', 'mcq', 'What is a transaction?', '["Sequence of operations", "Single operation", "Table operation", "Database operation"]', 'Sequence of operations', 'A transaction is a sequence of operations performed as a single unit.', 'active'),
('60000000-0000-0000-0000-000000000072', '50000000-0000-0000-0000-000000000006', 'intermediate', 'mcq', 'What is ACID compliance?', '["Atomicity, Consistency, Isolation, Durability", "Availability, Consistency, Integrity, Durability", "Atomicity, Consistency, Integrity, Durability", "Availability, Consistency, Isolation, Durability"]', 'Atomicity, Consistency, Isolation, Durability', 'ACID ensures reliable processing of database transactions.', 'active'),
('60000000-0000-0000-0000-000000000073', '50000000-0000-0000-0000-000000000006', 'intermediate', 'code_mcq', 'What does CREATE INDEX idx_name ON users (name); do?', '["Creates index on name column", "Creates table", "Creates view", "Creates constraint"]', 'Creates index on name column', 'This creates an index to improve queries on the name column.', 'active'),
('60000000-0000-0000-0000-000000000074', '50000000-0000-0000-0000-000000000006', 'expert', 'mcq', 'What are materialized views?', '["Precomputed query results", "Virtual tables", "Temporary tables", "Indexed views"]', 'Precomputed query results', 'Materialized views store query results physically for faster access.', 'active'),
('60000000-0000-0000-0000-000000000075', '50000000-0000-0000-0000-000000000006', 'expert', 'mcq', 'What is MVCC?', '["Multi-version concurrency control", "Multi-value concurrency control", "Multi-version consistency control", "Multi-value consistency control"]', 'Multi-version concurrency control', 'MVCC allows concurrent access without locking.', 'active'),
('60000000-0000-0000-0000-000000000076', '50000000-0000-0000-0000-000000000006', 'expert', 'mcq', 'What are window functions?', '["Perform calculations across rows", "Window operations", "Windowing functions", "Frame functions"]', 'Perform calculations across rows', 'Window functions perform calculations across related rows.', 'active'),
('60000000-0000-0000-0000-000000000077', '50000000-0000-0000-0000-000000000006', 'expert', 'code_mcq', 'What does WITH RECURSIVE enable?', '["Recursive queries", "Temporary tables", "Common table expressions", "All of the above"]', 'Recursive queries', 'WITH RECURSIVE enables recursive common table expressions.', 'active'),
('60000000-0000-0000-0000-000000000078', '50000000-0000-0000-0000-000000000006', 'expert', 'mcq', 'What is the default isolation level in PostgreSQL?', '["Read Committed", "Serializable", "Repeatable Read", "Read Uncommitted"]', 'Read Committed', 'Read Committed is the default isolation level in PostgreSQL.', 'active')
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000000079', '50000000-0000-0000-0000-000000000007', 'simple', 'mcq', 'What is TypeScript?', '["Typed superset of JavaScript", "New programming language", "JavaScript framework", "Database language"]', 'Typed superset of JavaScript', 'TypeScript adds static typing to JavaScript.', 'active'),
('60000000-0000-0000-0000-000000000080', '50000000-0000-0000-0000-000000000007', 'simple', 'mcq', 'What file extension does TypeScript use?', '[".ts", ".js", ".tsx", ".jsx"]', '.ts', 'TypeScript files use .ts extension.', 'active'),
('60000000-0000-0000-0000-000000000081', '50000000-0000-0000-0000-000000000007', 'simple', 'mcq', 'What does tsc do?', '["TypeScript compiler", "TypeScript checker", "TypeScript server", "TypeScript bundler"]', 'TypeScript compiler', 'tsc compiles TypeScript to JavaScript.', 'active'),
('60000000-0000-0000-0000-000000000082', '50000000-0000-0000-0000-000000000007', 'simple', 'code_mcq', 'What does this define? const name: string = "John";', '["Variable with string type", "Variable with any type", "Constant function", "Type alias"]', 'Variable with string type', 'This defines a constant variable with string type annotation.', 'active'),
('60000000-0000-0000-0000-000000000083', '50000000-0000-0000-0000-000000000007', 'intermediate', 'mcq', 'What is an interface?', '["Contract for object shape", "Type definition", "Class definition", "Function definition"]', 'Contract for object shape', 'Interfaces define the structure of objects.', 'active'),
('60000000-0000-0000-0000-000000000084', '50000000-0000-0000-0000-000000000007', 'intermediate', 'mcq', 'What are generics?', '["Type parameters", "Generic functions", "Template types", "All of the above"]', 'All of the above', 'Generics create reusable components that work with multiple types.', 'active'),
('60000000-0000-0000-0000-000000000085', '50000000-0000-0000-0000-000000000007', 'intermediate', 'mcq', 'What is type inference?', '["Automatic type detection", "Manual type annotation", "Type checking", "Type conversion"]', 'Automatic type detection', 'TypeScript can infer types without explicit annotations.', 'active'),
('60000000-0000-0000-0000-000000000086', '50000000-0000-0000-0000-000000000007', 'intermediate', 'code_mcq', 'What does Partial<T> do?', '["Makes all properties optional", "Makes all properties required", "Makes properties readonly", "Omits properties"]', 'Makes all properties optional', 'Partial<T> constructs a type with all properties of T set to optional.', 'active'),
('60000000-0000-0000-0000-000000000087', '50000000-0000-0000-0000-000000000007', 'expert', 'mcq', 'What are conditional types?', '["Types that depend on conditions", "If-else for types", "Type guards", "Type predicates"]', 'Types that depend on conditions', 'Conditional types select types based on conditions.', 'active'),
('60000000-0000-0000-0000-000000000088', '50000000-0000-0000-0000-000000000007', 'expert', 'mcq', 'What is declaration merging?', '["Merging multiple declarations", "Combining interfaces", "Extending types", "All of the above"]', 'All of the above', 'TypeScript can merge multiple declarations of the same name.', 'active'),
('60000000-0000-0000-0000-000000000089', '50000000-0000-0000-0000-000000000007', 'expert', 'mcq', 'What are mapped types?', '["Create new types by transforming properties", "Map functions", "Type mappings", "Property maps"]', 'Create new types by transforming properties', 'Mapped types create new types based on old ones by transforming properties.', 'active'),
('60000000-0000-0000-0000-000000000090', '50000000-0000-0000-0000-000000000007', 'expert', 'code_mcq', 'What does keyof T return?', '["Union of keys of T", "Type of keys", "Array of keys", "String of keys"]', 'Union of keys of T', 'keyof T returns a union type of the keys of type T.', 'active'),
('60000000-0000-0000-0000-000000000091', '50000000-0000-0000-0000-000000000007', 'expert', 'mcq', 'What is the unknown type?', '["Type-safe alternative to any", "Same as any", "Same as never", "Null value"]', 'Type-safe alternative to any', 'The unknown type is the type-safe counterpart of any.', 'active')
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000000092', '50000000-0000-0000-0000-000000000008', 'simple', 'mcq', 'What does CDN stand for?', '["Content Delivery Network", "Content Distribution Network", "Content Data Network", "Content Delivery Node"]', 'Content Delivery Network', 'CDNs distribute content geographically for faster delivery.', 'active'),
('60000000-0000-0000-0000-000000000093', '50000000-0000-0000-0000-000000000008', 'simple', 'mcq', 'What is lazy loading?', '["Loading resources when needed", "Loading all resources", "Loading on scroll", "Loading after page load"]', 'Loading resources when needed', 'Lazy loading defers loading of non-critical resources.', 'active'),
('60000000-0000-0000-0000-000000000094', '50000000-0000-0000-0000-000000000008', 'simple', 'mcq', 'What is XSS?', '["Cross-Site Scripting", "Cross-Site Security", "XML Site Scripting", "XHTML Site Scripting"]', 'Cross-Site Scripting', 'XSS allows attackers to inject malicious scripts.', 'active'),
('60000000-0000-0000-0000-000000000095', '50000000-0000-0000-0000-000000000008', 'simple', 'code_mcq', 'What does Cache-Control: max-age=3600 specify?', '["Cache for 1 hour", "Cache for 3600 hours", "No cache", "Cache validation"]', 'Cache for 1 hour', 'max-age=3600 means the resource can be cached for 3600 seconds (1 hour).', 'active'),
('60000000-0000-0000-0000-000000000096', '50000000-0000-0000-0000-000000000008', 'intermediate', 'mcq', 'What is tree shaking?', '["Removing unused code", "Shaking dependency tree", "Tree optimization", "Code splitting"]', 'Removing unused code', 'Tree shaking eliminates dead code during bundling.', 'active'),
('60000000-0000-0000-0000-000000000097', '50000000-0000-0000-0000-000000000008', 'intermediate', 'mcq', 'What is CORS?', '["Cross-Origin Resource Sharing", "Cross-Origin Request Security", "Cross-Origin Response Security", "Cross-Origin Resource Security"]', 'Cross-Origin Resource Sharing', 'CORS allows controlled access to resources from different origins.', 'active'),
('60000000-0000-0000-0000-000000000098', '50000000-0000-0000-0000-000000000008', 'intermediate', 'mcq', 'What is a CSRF token?', '["Prevents cross-site request forgery", "Authenticates users", "Encrypts data", "Validates forms"]', 'Prevents cross-site request forgery', 'CSRF tokens protect against unauthorized commands from users.', 'active'),
('60000000-0000-0000-0000-000000000099', '50000000-0000-0000-0000-000000000008', 'intermediate', 'code_mcq', 'What does Content-Security-Policy header do?', '["Controls resources", "Sets cookies", "Compresses content", "Redirects requests"]', 'Controls resources', 'CSP controls which resources can be loaded to prevent XSS.', 'active'),
('60000000-0000-0000-0000-000000000100', '50000000-0000-0000-0000-000000000008', 'expert', 'mcq', 'What is HSTS?', '["HTTP Strict Transport Security", "HTTP Secure Transport Security", "HTTP Strict Transfer Security", "HTTP Secure Transfer Security"]', 'HTTP Strict Transport Security', 'HSTS forces browsers to use HTTPS only.', 'active'),
('60000000-0000-0000-0000-000000000101', '50000000-0000-0000-0000-000000000008', 'expert', 'mcq', 'What are service workers?', '["Proxy between browser and network", "Web workers", "Background scripts", "JavaScript files"]', 'Proxy between browser and network', 'Service workers enable offline functionality and background sync.', 'active'),
('60000000-0000-0000-0000-000000000102', '50000000-0000-0000-0000-000000000008', 'expert', 'mcq', 'What is WebAssembly?', '["Binary instruction format", "JavaScript extension", "Web framework", "Markup language"]', 'Binary instruction format', 'WebAssembly enables near-native performance in web apps.', 'active'),
('60000000-0000-0000-0000-000000000103', '50000000-0000-0000-0000-000000000008', 'expert', 'code_mcq', 'What does Lighthouse measure?', '["Web performance", "Code quality", "Security score", "All of the above"]', 'All of the above', 'Lighthouse measures performance, accessibility, best practices, and SEO.', 'active'),
('60000000-0000-0000-0000-000000000104', '50000000-0000-0000-0000-000000000008', 'expert', 'mcq', 'What is the purpose of the SameSite cookie attribute?', '["Control cross-site cookie sending", "Set cookie expiration", "Secure cookie transfer", "Encrypt cookie data"]', 'Control cross-site cookie sending', 'SameSite prevents cookies from being sent with cross-site requests to mitigate CSRF.', 'active')
