INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000000105', '50000000-0000-0000-0000-000000000009', 'simple', 'mcq', 'What is the primary goal of data cleaning?', '["To make data visually appealing", "To remove or correct errors in data", "To increase data volume", "To encrypt data"]', 'To remove or correct errors in data', 'Data cleaning involves identifying and correcting inaccuracies to ensure reliable analysis.', 'active'),
('60000000-0000-0000-0000-000000000106', '50000000-0000-0000-0000-000000000009', 'simple', 'mcq', 'Which Python library is commonly used for handling missing values?', '["NumPy", "Pandas", "Matplotlib", "Seaborn"]', 'Pandas', 'Pandas provides functions like dropna() and fillna() for missing values.', 'active'),
('60000000-0000-0000-0000-000000000107', '50000000-0000-0000-0000-000000000009', 'simple', 'code_mcq', 'What does df.dropna() do in Pandas?', '["Removes rows with missing values", "Fills missing values", "Duplicates rows", "Sorts the dataframe"]', 'Removes rows with missing values', 'dropna() removes rows or columns with NaN values.', 'active'),
('60000000-0000-0000-0000-000000000108', '50000000-0000-0000-0000-000000000009', 'simple', 'mcq', 'What is a common method to handle outliers?', '["Ignore them", "Remove or cap them", "Multiply them", "Encrypt them"]', 'Remove or cap them', 'Outliers can be removed or capped to prevent skewing results.', 'active'),
('60000000-0000-0000-0000-000000000109', '50000000-0000-0000-0000-000000000009', 'intermediate', 'mcq', 'How can you detect duplicate rows in a Pandas DataFrame?', '["df.unique()", "df.duplicated()", "df.distinct()", "df.repeat()"]', 'df.duplicated()', 'duplicated() returns a boolean series indicating duplicates.', 'active'),
('60000000-0000-0000-0000-000000000110', '50000000-0000-0000-0000-000000000009', 'intermediate', 'code_mcq', 'What is the output of df.fillna(0)?', '["Replaces NaN with 0", "Drops NaN", "Counts NaN", "Ignores NaN"]', 'Replaces NaN with 0', 'fillna() replaces missing values with a specified value.', 'active'),
('60000000-0000-0000-0000-000000000111', '50000000-0000-0000-0000-000000000009', 'intermediate', 'mcq', 'What does imputation mean in data cleaning?', '["Removing data", "Filling missing values", "Sorting data", "Encrypting data"]', 'Filling missing values', 'Imputation replaces missing data with substituted values.', 'active'),
('60000000-0000-0000-0000-000000000112', '50000000-0000-0000-0000-000000000009', 'intermediate', 'code_mcq', 'Which method standardizes string cases in Pandas?', '["str.lower()", "str.upper()", "str.case()", "str.norm()"]', 'str.lower()', 'str.lower() normalizes text by converting to lowercase.', 'active'),
('60000000-0000-0000-0000-000000000113', '50000000-0000-0000-0000-000000000009', 'expert', 'mcq', 'What is the impact of multicollinearity in data analysis?', '["Improves model accuracy", "Causes unstable coefficients", "Reduces computation time", "Increases data volume"]', 'Causes unstable coefficients', 'Multicollinearity makes it hard to assess individual predictor effects.', 'active'),
('60000000-0000-0000-0000-000000000114', '50000000-0000-0000-0000-000000000009', 'expert', 'code_mcq', 'How do you handle categorical outliers in Pandas?', '["Use IQR method", "Mode imputation", "One-hot encoding first", "Custom frequency thresholds"]', 'Custom frequency thresholds', 'Rare categories can be grouped or thresholded based on frequency.', 'active'),
('60000000-0000-0000-0000-000000000115', '50000000-0000-0000-0000-000000000009', 'expert', 'mcq', 'What is winsorization?', '["Capping outliers", "Removing duplicates", "Filling NaN", "Normalizing data"]', 'Capping outliers', 'Winsorization limits extreme values to reduce outlier impact.', 'active'),
('60000000-0000-0000-0000-000000000116', '50000000-0000-0000-0000-000000000009', 'expert', 'code_mcq', 'What does this scikit-learn code do? IsolationForest().fit(df)', '["Fits a clustering model", "Detects outliers using isolation", "Performs regression", "Visualizes data"]', 'Detects outliers using isolation', 'Isolation Forest isolates anomalies instead of profiling normal points.', 'active'),
('60000000-0000-0000-0000-000000000117', '50000000-0000-0000-0000-000000000009', 'expert', 'mcq', 'How does SMOTE handle imbalanced data?', '["Undersampling majority", "Oversampling minority with synthetics", "Removing samples", "Shuffling data"]', 'Oversampling minority with synthetics', 'SMOTE creates synthetic examples for the minority class.', 'active')
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000000118', '50000000-0000-0000-0000-000000000010', 'simple', 'mcq', 'What is feature engineering?', '["Creating new features from existing data", "Cleaning data", "Visualizing data", "Training models"]', 'Creating new features from existing data', 'It transforms raw data into features that better represent the problem.', 'active'),
('60000000-0000-0000-0000-000000000119', '50000000-0000-0000-0000-000000000010', 'simple', 'mcq', 'What is one-hot encoding used for?', '["Converting categorical to numerical", "Scaling numerical features", "Removing outliers", "Filling missing values"]', 'Converting categorical to numerical', 'It creates binary columns for each category.', 'active'),
('60000000-0000-0000-0000-000000000120', '50000000-0000-0000-0000-000000000010', 'simple', 'code_mcq', 'What does pd.get_dummies() do?', '["Creates dummy variables", "Drops duplicates", "Fills NaN", "Sorts data"]', 'Creates dummy variables', 'It performs one-hot encoding on categorical columns.', 'active'),
('60000000-0000-0000-0000-000000000121', '50000000-0000-0000-0000-000000000010', 'simple', 'mcq', 'Why normalize features in machine learning?', '["To make them same scale", "To remove them", "To duplicate them", "To encrypt them"]', 'To make them same scale', 'Normalization helps algorithms converge faster.', 'active'),
('60000000-0000-0000-0000-000000000122', '50000000-0000-0000-0000-000000000010', 'intermediate', 'mcq', 'What is label encoding?', '["Assigning integers to categories", "Creating binary features", "Scaling to 0-1", "Binning continuous"]', 'Assigning integers to categories', 'It converts categories to numerical labels.', 'active'),
('60000000-0000-0000-0000-000000000123', '50000000-0000-0000-0000-000000000010', 'intermediate', 'code_mcq', 'What is the purpose of MinMaxScaler?', '["Scales to range [0,1]", "Standardizes to mean 0", "Encodes categories", "Bins data"]', 'Scales to range [0,1]', 'It transforms features to a given range.', 'active'),
('60000000-0000-0000-0000-000000000124', '50000000-0000-0000-0000-000000000010', 'intermediate', 'mcq', 'What is polynomial feature generation?', '["Creating interaction terms", "Removing features", "Scaling features", "Encoding text"]', 'Creating interaction terms', 'It generates higher-degree terms for non-linear relationships.', 'active'),
('60000000-0000-0000-0000-000000000125', '50000000-0000-0000-0000-000000000010', 'intermediate', 'code_mcq', 'How do you create binned features in Pandas?', '["pd.cut()", "pd.split()", "pd.bin()", "pd.group()"]', 'pd.cut()', 'pd.cut() discretizes continuous features into bins.', 'active'),
('60000000-0000-0000-0000-000000000126', '50000000-0000-0000-0000-000000000010', 'expert', 'mcq', 'What is target encoding?', '["Encoding categories based on target mean", "One-hot with target", "Label encoding", "Frequency encoding"]', 'Encoding categories based on target mean', 'It replaces categories with the mean target value.', 'active'),
('60000000-0000-0000-0000-000000000127', '50000000-0000-0000-0000-000000000010', 'expert', 'code_mcq', 'What does PolynomialFeatures(degree=2) in scikit-learn generate?', '["Squared and interaction terms", "Only squares", "Linear terms", "Exponential terms"]', 'Squared and interaction terms', 'It creates polynomial and interaction features.', 'active'),
('60000000-0000-0000-0000-000000000128', '50000000-0000-0000-0000-000000000010', 'expert', 'mcq', 'How to handle high cardinality in categorical features?', '["Target encoding or hashing", "One-hot all", "Drop column", "Label encode"]', 'Target encoding or hashing', 'Reduces dimensionality for high unique values.', 'active'),
('60000000-0000-0000-0000-000000000129', '50000000-0000-0000-0000-000000000010', 'expert', 'code_mcq', 'What is scikit-learn''s FeatureHasher used for?', '["Hashing high-dimensional categoricals", "Scaling features", "Binning", "Polynomial expansion"]', 'Hashing high-dimensional categoricals', 'It applies the hashing trick for feature vectorization.', 'active'),
('60000000-0000-0000-0000-000000000130', '50000000-0000-0000-0000-000000000010', 'expert', 'mcq', 'What is an interaction feature in modeling?', '["Product of two features", "Sum of features", "Difference only", "Ratio only"]', 'Product of two features', 'Captures combined effects between features.', 'active')
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000000131', '50000000-0000-0000-0000-000000000011', 'simple', 'mcq', 'What does linear regression predict?', '["Continuous values", "Categories", "Clusters", "Associations"]', 'Continuous values', 'It models the relationship between variables for continuous output.', 'active'),
('60000000-0000-0000-0000-000000000132', '50000000-0000-0000-0000-000000000011', 'simple', 'mcq', 'What is the standard cost function for linear regression?', '["Mean Squared Error", "Cross-Entropy", "Gini Index", "Entropy"]', 'Mean Squared Error', 'MSE measures the average squared difference between predictions and actuals.', 'active'),
('60000000-0000-0000-0000-000000000133', '50000000-0000-0000-0000-000000000011', 'simple', 'code_mcq', 'What does LinearRegression().fit(X, y) do?', '["Trains the model", "Predicts values", "Scales data", "Encodes labels"]', 'Trains the model', 'fit() estimates the coefficients by minimizing the cost function.', 'active'),
('60000000-0000-0000-0000-000000000134', '50000000-0000-0000-0000-000000000011', 'simple', 'mcq', 'What does R-squared indicate?', '["Proportion of variance explained", "Error rate", "Accuracy", "Precision"]', 'Proportion of variance explained', 'It indicates how well the independent variables explain the dependent variable.', 'active'),
('60000000-0000-0000-0000-000000000135', '50000000-0000-0000-0000-000000000011', 'intermediate', 'mcq', 'What is Ridge regression?', '["L2 regularization", "L1 regularization", "No regularization", "Elastic Net"]', 'L2 regularization', 'It adds a squared penalty to coefficients to prevent overfitting.', 'active'),
('60000000-0000-0000-0000-000000000136', '50000000-0000-0000-0000-000000000011', 'intermediate', 'code_mcq', 'What does the alpha parameter in Ridge control?', '["Regularization strength", "Learning rate", "Batch size", "Tree depth"]', 'Regularization strength', 'Higher alpha increases the penalty, reducing coefficient size.', 'active'),
('60000000-0000-0000-0000-000000000137', '50000000-0000-0000-0000-000000000011', 'intermediate', 'mcq', 'What is the main advantage of Lasso over Ridge?', '["Feature selection via L1", "Better performance on all data", "Computational speed", "No advantage"]', 'Feature selection via L1', 'Lasso can shrink some coefficients exactly to zero, performing feature selection.', 'active'),
('60000000-0000-0000-0000-000000000138', '50000000-0000-0000-0000-000000000011', 'intermediate', 'code_mcq', 'Which scikit-learn function calculates Mean Squared Error?', '["mean_squared_error()", "calculate_mse()", "mse_score()", "regression_error()"]', 'mean_squared_error()', 'This is the standard function in metrics for regression error.', 'active'),
('60000000-0000-0000-0000-000000000139', '50000000-0000-0000-0000-000000000011', 'expert', 'mcq', 'What is Elastic Net regression?', '["Weighted combination of L1 and L2", "Dynamic regularization", "Neural network regression", "Non-linear regression"]', 'Weighted combination of L1 and L2', 'It combines L1 and L2 penalties to balance feature selection and stability.', 'active'),
('60000000-0000-0000-0000-000000000140', '50000000-0000-0000-0000-000000000011', 'expert', 'code_mcq', 'What does GridSearchCV optimize in a regression model?', '["Hyperparameters", "Data splits", "Feature counts", "Visualization parameters"]', 'Hyperparameters', 'It searches the parameter grid for the best alpha, depth, etc.', 'active'),
('60000000-0000-0000-0000-000000000141', '50000000-0000-0000-0000-000000000011', 'expert', 'mcq', 'How do you handle non-linearity in linear models?', '["Polynomial transformation", "More data", "Removing outliers", "Linear intercept only"]', 'Polynomial transformation', 'Creating higher-degree features allows linear models to capture non-linear trends.', 'active'),
('60000000-0000-0000-0000-000000000142', '50000000-0000-0000-0000-000000000011', 'expert', 'code_mcq', 'What is the role of learning_rate in GradientBoostingRegressor?', '["Shrinks contribution of each tree", "Sets the maximum depth", "Sets number of trees", "Sets random seed"]', 'Shrinks contribution of each tree', 'It prevents overfitting by making each tree contribute less to the final prediction.', 'active'),
('60000000-0000-0000-0000-000000000143', '50000000-0000-0000-0000-000000000011', 'expert', 'mcq', 'What is heteroscedasticity?', '["Non-constant variance of residuals", "Linear relationship only", "Normal distribution of features", "Zero mean residuals"]', 'Non-constant variance of residuals', 'It violates the homoscedasticity assumption in linear regression.', 'active')
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000000144', '50000000-0000-0000-0000-000000000012', 'simple', 'mcq', 'What does logistic regression predict?', '["Probabilities of class membership", "Continuous values", "Cluster centroids", "Association rules"]', 'Probabilities of class membership', 'It uses the sigmoid function to map values between 0 and 1.', 'active'),
('60000000-0000-0000-0000-000000000145', '50000000-0000-0000-0000-000000000012', 'simple', 'mcq', 'How is accuracy defined in classification?', '["Correct predictions divided by total", "True positives divided by total positives", "False positives divided by total negatives", "Precision plus recall"]', 'Correct predictions divided by total', 'It is the most basic metric for overall classification performance.', 'active'),
('60000000-0000-0000-0000-000000000146', '50000000-0000-0000-0000-000000000012', 'simple', 'code_mcq', 'What does LogisticRegression().predict_proba(X) return?', '["Class probabilities", "Discrete class labels", "Model coefficients", "Intercept value"]', 'Class probabilities', 'It provides the estimated probability for each target class.', 'active'),
('60000000-0000-0000-0000-000000000147', '50000000-0000-0000-0000-000000000012', 'simple', 'mcq', 'What is a decision tree?', '["A model that splits data based on feature values", "A linear regression ensemble", "A clustering algorithm", "Feature reduction method"]', 'A model that splits data based on feature values', 'It creates a tree-like structure of decisions and their possible consequences.', 'active'),
('60000000-0000-0000-0000-000000000148', '50000000-0000-0000-0000-000000000012', 'intermediate', 'mcq', 'What is precision in classification results?', '["True positives divided by predicted positives", "True positives divided by actual positives", "Total correct over total samples", "Harmonic mean of recall"]', 'True positives divided by predicted positives', 'Precision measures how many of the positive predictions were actually correct.', 'active'),
('60000000-0000-0000-0000-000000000149', '50000000-0000-0000-0000-000000000012', 'intermediate', 'code_mcq', 'What information does classification_report() provide?', '["Precision, recall, and F1-score", "Only accuracy", "Confusion matrix only", "ROC curve data"]', 'Precision, recall, and F1-score', 'This scikit-learn helper gives a comprehensive summary of model performance.', 'active'),
('60000000-0000-0000-0000-000000000150', '50000000-0000-0000-0000-000000000012', 'intermediate', 'mcq', 'What is a Random Forest?', '["An ensemble of decision trees", "A single optimized tree", "A weighted linear model", "A support vector machine variant"]', 'An ensemble of decision trees', 'It uses bagging and feature randomness to create a forest of uncorrelated trees.', 'active'),
('60000000-0000-0000-0000-000000000151', '50000000-0000-0000-0000-000000000012', 'intermediate', 'code_mcq', 'What does n_estimators in GaussianNB or RandomForest do?', '["Specifies the number of base estimators (trees)", "Sets the learning rate", "Sets max depth", "Sets random state"]', 'Specifies the number of base estimators (trees)', 'In ensemble models, it defines how many models contribute to the result.', 'active'),
('60000000-0000-0000-0000-000000000152', '50000000-0000-0000-0000-000000000012', 'expert', 'mcq', 'What is the AUC-ROC score?', '["Area under the receiver operating characteristic curve", "Accuracy under complexity", "Average uniform correlation", "Precision-recall integral"]', 'Area under the receiver operating characteristic curve', 'It measures the ability of a classifier to distinguish between classes across thresholds.', 'active'),
('60000000-0000-0000-0000-000000000153', '50000000-0000-0000-0000-000000000012', 'expert', 'code_mcq', 'How can you handle class imbalance in a dataset?', '["SMOTE or class weighting", "Removing features", "Normalizing labels", "Sorting data"]', 'SMOTE or class weighting', 'SMOTE generates synthetic samples for the minority class to balance the training set.', 'active'),
('60000000-0000-0000-0000-000000000154', '50000000-0000-0000-0000-000000000012', 'expert', 'mcq', 'What is Gradient Boosting for classification?', '["Building trees sequentially to minimize residual errors", "Building trees in parallel", "Building a single deep tree", "A linear method"]', 'Building trees sequentially to minimize residual errors', 'Each new tree works on the error left over by previous trees.', 'active'),
('60000000-0000-0000-0000-000000000155', '50000000-0000-0000-0000-000000000012', 'expert', 'code_mcq', 'What is the purpose of the kernel in SVC?', '["Transforms data into higher-dimensional space", "Specifies the number of trees", "Sets the learning rate", "Optimizes batch size"]', 'Transforms data into higher-dimensional space', 'The kernel trick allows SVM to create non-linear decision boundaries.', 'active'),
('60000000-0000-0000-0000-000000000156', '50000000-0000-0000-0000-000000000012', 'expert', 'mcq', 'What is Focal Loss used for in deep classification?', '["Focusing on hard-to-classify examples", "Handling outliers", "Minimizing MSE", "Standard categorization"]', 'Focusing on hard-to-classify examples', 'It down-weights easy examples and focuses training on hard negatives/positives.', 'active')
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000000157', '50000000-0000-0000-0000-000000000013', 'simple', 'mcq', 'What is the primary goal of clustering in machine learning?', '["Grouping similar data points together", "Predicting numerical values", "Reducing feature count", "Classifying labeled data"]', 'Grouping similar data points together', 'Clustering is an unsupervised learning task that finds natural groupings in data.', 'active'),
('60000000-0000-0000-0000-000000000158', '50000000-0000-0000-0000-000000000013', 'simple', 'mcq', 'What is K-means clustering?', '["A method that partitions data into K distinct clusters", "A hierarchical grouping method", "A density-based algorithm", "A linear regression variant"]', 'A method that partitions data into K distinct clusters', 'It assigns each point to the cluster with the nearest mean (centroid).', 'active'),
('60000000-0000-0000-0000-000000000159', '50000000-0000-0000-0000-000000000013', 'simple', 'code_mcq', 'What does KMeans(n_clusters=3).fit(X) do?', '["Learns the centroids for 3 clusters", "Predicts labels for 3 points", "Scales data into 3 ranges", "Splits data into 3 batches"]', 'Learns the centroids for 3 clusters', 'The fit method calculates the position of the centroids based on the input data.', 'active'),
('60000000-0000-0000-0000-000000000160', '50000000-0000-0000-0000-000000000013', 'simple', 'mcq', 'What is the elbow method used for in clustering?', '["Finding the optimal number of clusters (K)", "Determining cluster depth", "Calculating cluster variance", "Visualizing 3D clusters"]', 'Finding the optimal number of clusters (K)', 'It plots the variance explained as a function of the number of clusters.', 'active'),
('60000000-0000-0000-0000-000000000161', '50000000-0000-0000-0000-000000000013', 'intermediate', 'mcq', 'What is hierarchical clustering?', '["A method that builds a tree of clusters", "A flat partitioning method", "A neural network approach", "A reinforcement learning method"]', 'A method that builds a tree of clusters', 'It produces a dendrogram representing the nested grouping of patterns.', 'active'),
('60000000-0000-0000-0000-000000000162', '50000000-0000-0000-0000-000000000013', 'intermediate', 'code_mcq', 'What does silhouette_score() measure in clustering?', '["How similar an object is to its own cluster compared to others", "Total within-cluster sum of squares", "Accuracy against ground truth", "Number of outliers"]', 'How similar an object is to its own cluster compared to others', 'Higher silhouette values indicate better-defined clusters.', 'active'),
('60000000-0000-0000-0000-000000000163', '50000000-0000-0000-0000-000000000013', 'intermediate', 'mcq', 'What is the main advantage of DBSCAN?', '["It can find clusters of arbitrary shapes", "It is faster than K-means", "It always finds a fixed number of clusters", "It works only on linear data"]', 'It can find clusters of arbitrary shapes', 'DBSCAN uses density to group points and can identify noise (outliers).', 'active'),
('60000000-0000-0000-0000-000000000164', '50000000-0000-0000-0000-000000000013', 'intermediate', 'code_mcq', 'Which parameters are crucial for DBSCAN in scikit-learn?', '["eps and min_samples", "n_clusters and init", "depth and learning_rate", "penalty and alpha"]', 'eps and min_samples', 'eps defines the neighborhood radius, and min_samples is the minimum points to form a core.', 'active'),
('60000000-0000-0000-0000-000000000165', '50000000-0000-0000-0000-000000000013', 'expert', 'mcq', 'What is spectral clustering?', '["Grouping based on the eigenvalues of data similarity matrices", "Clustering using rainbow charts", "A variant of logistic regression", "Clustering only continuous data"]', 'Grouping based on the eigenvalues of data similarity matrices', 'It performs dimensionality reduction using the Laplacian matrix before clustering.', 'active'),
('60000000-0000-0000-0000-000000000166', '50000000-0000-0000-0000-000000000013', 'expert', 'code_mcq', 'When would you use MiniBatchKMeans instead of KMeans?', '["When working with very large datasets", "When you need higher precision", "When data is 1-dimensional", "When labels are provided"]', 'When working with very large datasets', 'MiniBatchKMeans uses small random batches of data to reduce computation time.', 'active'),
('60000000-0000-0000-0000-000000000167', '50000000-0000-0000-0000-000000000013', 'expert', 'mcq', 'What is the "curse of dimensionality" in the context of clustering?', '["Distance metrics become less meaningful as dimensions increase", "Higher dimensions lead to fewer clusters", "Data becomes too dense to cluster", "Computational cost becomes zero"]', 'Distance metrics become less meaningful as dimensions increase', 'High-dimensional space makes all points appear equidistant.', 'active'),
('60000000-0000-0000-0000-000000000168', '50000000-0000-0000-0000-000000000013', 'expert', 'code_mcq', 'What does linkage="ward" do in AgglomerativeClustering?', '["Minimizes the variance of clusters being merged", "Merges based on maximum distance", "Merges based on distance between centroids", "Merges based on average distance"]', 'Minimizes the variance of clusters being merged', 'Ward''s method is often the default as it creates more compact clusters.', 'active'),
('60000000-0000-0000-0000-000000000169', '50000000-0000-0000-0000-000000000013', 'expert', 'mcq', 'What is the primary difference between Hard and Soft clustering?', '["Soft clustering assigns probabilities of membership", "Hard clustering allows overlaps", "There is no difference", "Soft clustering is for categorical data"]', 'Soft clustering assigns probabilities of membership', 'Soft clustering (like GMM) gives a point a degree of belonging to each cluster.', 'active')
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000000170', '50000000-0000-0000-0000-000000000014', 'simple', 'mcq', 'What does PCA stand for?', '["Principal Component Analysis", "Partial Cluster Alpha", "Predictive Correlation Algorithm", "Polynomial Centroid Analysis"]', 'Principal Component Analysis', 'PCA is the most common linear dimensionality reduction technique.', 'active'),
('60000000-0000-0000-0000-000000000171', '50000000-0000-0000-0000-000000000014', 'simple', 'mcq', 'Why is dimensionality reduction performed?', '["To simplify models and improve visualization", "To add more noise to data", "To increase training time", "To make data harder to read"]', 'To simplify models and improve visualization', 'Reducing features can prevent overfitting and allow 2D/3D plotting.', 'active'),
('60000000-0000-0000-0000-000000000172', '50000000-0000-0000-0000-000000000014', 'simple', 'code_mcq', 'What does PCA(n_components=2).fit_transform(X) do?', '["Projects data onto the top 2 principal components", "Splits data into 2 clusters", "Selects the first 2 columns", "Normalizes data by 2"]', 'Projects data onto the top 2 principal components', 'It transforms high-dimensional data into a 2D space while preserving variance.', 'active'),
('60000000-0000-0000-0000-000000000173', '50000000-0000-0000-0000-000000000014', 'simple', 'mcq', 'What is "explained variance ratio" in PCA?', '["The percentage of variance each principal component captures", "The error rate of the projection", "The distance between centroids", "The number of features removed"]', 'The percentage of variance each principal component captures', 'It helps decide how many components to keep.', 'active'),
('60000000-0000-0000-0000-000000000174', '50000000-0000-0000-0000-000000000014', 'intermediate', 'mcq', 'What is t-SNE primarily used for?', '["Visualizing high-dimensional data in 2D or 3D", "Linear feature selection", "Real-time regression", "Database indexing"]', 'Visualizing high-dimensional data in 2D or 3D', 't-SNE preserves local structures, making it great for finding clusters visually.', 'active'),
('60000000-0000-0000-0000-000000000175', '50000000-0000-0000-0000-000000000014', 'intermediate', 'code_mcq', 'What does the perplexity parameter in t-SNE balance?', '["Local and global aspects of the data", "Learning rate and inertia", "Number of components and CPU usage", "Accuracy and precision"]', 'Local and global aspects of the data', 'Perplexity is roughly the number of nearest neighbors each point considers.', 'active'),
('60000000-0000-0000-0000-000000000176', '50000000-0000-0000-0000-000000000014', 'intermediate', 'mcq', 'How does LDA differ from PCA in reduction?', '["LDA is supervised and uses class labels", "PCA is supervised", "They are identical", "LDA is only for regression"]', 'LDA is supervised and uses class labels', 'Linear Discriminant Analysis maximizes the separation between multiple classes.', 'active'),
('60000000-0000-0000-0000-000000000177', '50000000-0000-0000-0000-000000000014', 'intermediate', 'code_mcq', 'How do you check cumulative variance in scikit-learn PCA?', '["pca.explained_variance_ratio_.cumsum()", "pca.total_variance()", "pca.variance_sum", "pca.get_ratio()"]', 'pca.explained_variance_ratio_.cumsum()', 'This shows how much total variance is explained as you add components.', 'active'),
('60000000-0000-0000-0000-000000000178', '50000000-0000-0000-0000-000000000014', 'expert', 'mcq', 'What is UMAP?', '["Uniform Manifold Approximation and Projection", "Unified Model Alpha Process", "Unsupervised Mapping Pattern", "Universal Matrix Projection"]', 'Uniform Manifold Approximation and Projection', 'UMAP is a fast non-linear reduction technique that preserves more global structure than t-SNE.', 'active'),
('60000000-0000-0000-0000-000000000179', '50000000-0000-0000-0000-000000000014', 'expert', 'code_mcq', 'What is TruncatedSVD useful for?', '["Sparse matrices and text data", "Dense video data only", "1D signals", "Label encoding"]', 'Sparse matrices and text data', 'TruncatedSVD doesn''t center data, making it compatible with sparse arrays (like TF-IDF).', 'active'),
('60000000-0000-0000-0000-000000000180', '50000000-0000-0000-0000-000000000014', 'expert', 'mcq', 'How do Autoencoders perform dimensionality reduction?', '["By learning a compressed representation in the bottleneck layer", "By removing columns randomly", "By performing linear projection only", "By clustering labels"]', 'By learning a compressed representation in the bottleneck layer', 'Neural network autoencoders learn non-linear mappings to lower dimensions.', 'active'),
('60000000-0000-0000-0000-000000000181', '50000000-0000-0000-0000-000000000014', 'expert', 'code_mcq', 'What is Isomap based on?', '["Preserving geodesic distances on a manifold", "Preserving Euclidean distances only", "Maximizing class variance", "Minimizing entropy"]', 'Preserving geodesic distances on a manifold', 'Isomap is a non-linear method that uses graph distances to approximate the manifold.', 'active'),
('60000000-0000-0000-0000-000000000182', '50000000-0000-0000-0000-000000000014', 'expert', 'mcq', 'What is the "Kernel" in Kernel PCA used for?', '["Allowing non-linear projections", "Speeding up computation", "Reducing memory usage", "Handling missing values"]', 'Allowing non-linear projections', 'The kernel trick allows PCA to operate in high-dimensional feature spaces.', 'active')
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000000183', '50000000-0000-0000-0000-000000000015', 'simple', 'mcq', 'What is a p-value?', '["Probability of observing results as extreme as the actual results, assuming the null hypothesis is true", "Probability that the alternative hypothesis is true", "The error rate of the model", "The confidence level percentage"]', 'Probability of observing results as extreme as the actual results, assuming the null hypothesis is true', 'A small p-value (<0.05) suggests strong evidence against the null hypothesis.', 'active'),
('60000000-0000-0000-0000-000000000184', '50000000-0000-0000-0000-000000000015', 'simple', 'mcq', 'What is hypothesis testing?', '["Making inferences about a population parameter based on sample data", "Describing data using charts", "Predicting future stock prices", "Calculating the average of a list"]', 'Making inferences about a population parameter based on sample data', 'It involves testing a null hypothesis against an alternative hypothesis.', 'active'),
('60000000-0000-0000-0000-000000000185', '50000000-0000-0000-0000-000000000015', 'simple', 'code_mcq', 'What does scipy.stats.ttest_ind() compare?', '["Means of two independent groups", "Variance of one group", "Standard deviation of three groups", "Correlation of two variables"]', 'Means of two independent groups', 'It performs an independent t-test to check if group means are significantly different.', 'active'),
('60000000-0000-0000-0000-000000000186', '50000000-0000-0000-0000-000000000015', 'simple', 'mcq', 'What is a confidence interval?', '["A range of values likely to contain the true population parameter", "The exact value of the population mean", "The range between min and max data points", "A measure of data cleaning quality"]', 'A range of values likely to contain the true population parameter', 'A 95% CI means we are 95% confident the true parameter lies within the range.', 'active'),
('60000000-0000-0000-0000-000000000187', '50000000-0000-0000-0000-000000000015', 'intermediate', 'mcq', 'What is a Type I error?', '["Rejecting a true null hypothesis (False Positive)", "Failing to reject a false null hypothesis", "Incorrectly calculating the mean", "Choosing the wrong model"]', 'Rejecting a true null hypothesis (False Positive)', 'It is often denoted by alpha (significance level).', 'active'),
('60000000-0000-0000-0000-000000000188', '50000000-0000-0000-0000-000000000015', 'intermediate', 'code_mcq', 'Which test is used for categorical association in scipy?', '["chi2_contingency()", "ttest_rel()", "f_oneway()", "pearsonr()"]', 'chi2_contingency()', 'The Chi-square test checks for independence between categorical variables.', 'active'),
('60000000-0000-0000-0000-000000000189', '50000000-0000-0000-0000-000000000015', 'intermediate', 'mcq', 'What is ANOVA used for?', '["Comparing means across three or more groups", "Comparing two groups only", "Testing for normality only", "Linear regression optimization"]', 'Comparing means across three or more groups', 'Analysis of Variance checks if at least one group mean is different.', 'active'),
('60000000-0000-0000-0000-000000000190', '50000000-0000-0000-0000-000000000015', 'intermediate', 'code_mcq', 'What does pearsonr() return in scipy.stats?', '["Correlation coefficient and p-value", "Only correlation", "Slope and intercept", "Mean and variance"]', 'Correlation coefficient and p-value', 'It measures the linear relationship between two continuous variables.', 'active'),
('60000000-0000-0000-0000-000000000191', '50000000-0000-0000-0000-000000000015', 'expert', 'mcq', 'What is multiple testing correction?', '["Adjusting p-values to control family-wise error rate", "Running the same test multiple times", "Increasing the sample size", "Averaging p-values from different tests"]', 'Adjusting p-values to control family-wise error rate', 'Methods like Bonferroni or False Discovery Rate (FDR) are used.', 'active'),
('60000000-0000-0000-0000-000000000192', '50000000-0000-0000-0000-000000000015', 'expert', 'code_mcq', 'How do you perform OLS regression with statistical summaries in Python?', '["statsmodels.api.OLS()", "sklearn.LinearRegression()", "scipy.optimize()", "pandas.regret()"]', 'statsmodels.api.OLS()', 'statsmodels provides detailed p-values and R-squared summaries for regression.', 'active'),
('60000000-0000-0000-0000-000000000193', '50000000-0000-0000-0000-000000000015', 'expert', 'mcq', 'What is Bayesian Inference?', '["Updating the probability of a hypothesis as more evidence becomes available", "Strictly using p-values", "Frequentist approach only", "Random guessing based on charts"]', 'Updating the probability of a hypothesis as more evidence becomes available', 'It uses prior beliefs and the likelihood function to calculate the posterior.', 'active'),
('60000000-0000-0000-0000-000000000194', '50000000-0000-0000-0000-000000000015', 'expert', 'code_mcq', 'What is the Shapiro-Wilk test used for?', '["Testing if a distribution is normal", "Comparing variances", "Finding outliers", "Clustering efficiency"]', 'Testing if a distribution is normal', 'In scipy, shapiro() returns the test statistic and p-value for normality.', 'active'),
('60000000-0000-0000-0000-000000000195', '50000000-0000-0000-0000-000000000015', 'expert', 'mcq', 'What is Power in statistical testing?', '["The probability of correctly rejecting a false null hypothesis", "The square of p-value", "The number of observations", "The significance level"]', 'The probability of correctly rejecting a false null hypothesis', 'Power (1 - beta) is the ability to detect an effect when it exists.', 'active')
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000000196', '50000000-0000-0000-0000-000000000016', 'simple', 'mcq', 'What is a histogram primarily used for?', '["Showing the distribution of a continuous variable", "Comparing discrete categories", "Visualizing time series only", "Plotting 3D points"]', 'Showing the distribution of a continuous variable', 'It groups data into bins and shows the frequency of each bin.', 'active'),
('60000000-0000-0000-0000-000000000197', '50000000-0000-0000-0000-000000000016', 'simple', 'mcq', 'Which Python library is the foundation for most plotting?', '["Matplotlib", "NumPy", "TensorFlow", "Requests"]', 'Matplotlib', 'Matplotlib is the core library for creating static, animated, and interactive visualizations.', 'active'),
('60000000-0000-0000-0000-000000000198', '50000000-0000-0000-0000-000000000016', 'simple', 'code_mcq', 'What does plt.scatter(x, y) plot?', '["Individual points representing data pairs", "A continuous line", "Bar charts", "Pie segments"]', 'Individual points representing data pairs', 'Scatter plots are used to observe relationships between two variables.', 'active'),
('60000000-0000-0000-0000-000000000199', '50000000-0000-0000-0000-000000000016', 'simple', 'mcq', 'What is a Box Plot (Whiskers plot) useful for?', '["Visualizing quartiles, median, and outliers", "Plotting frequency of text", "Network graphs", "Mapping geographic data"]', 'Visualizing quartiles, median, and outliers', 'It provides a summary of the distribution and highlights anomalies.', 'active'),
('60000000-0000-0000-0000-000000000200', '50000000-0000-0000-0000-000000000016', 'intermediate', 'mcq', 'What is Seaborn?', '["A statistical visualization library built on Matplotlib", "A database engine", "A web scraping tool", "A machine learning pipeline"]', 'A statistical visualization library built on Matplotlib', 'Seaborn provides a high-level interface for drawing attractive statistical graphics.', 'active'),
('60000000-0000-0000-0000-000000000201', '50000000-0000-0000-0000-000000000016', 'intermediate', 'code_mcq', 'What does sns.heatmap() visualize?', '["A matrix of data with color encoding", "A scatter plot with labels", "A 3D surface", "A pie chart with 10 slices"]', 'A matrix of data with color encoding', 'Heatmaps are commonly used for correlation matrices or confusion matrices.', 'active'),
('60000000-0000-0000-0000-000000000202', '50000000-0000-0000-0000-000000000016', 'intermediate', 'mcq', 'What is a "Pair Plot" in Seaborn?', '["A grid of scatter plots for every pair of variables", "A plot with two lines", "A plot comparing only two categories", "A bar chart with pairs"]', 'A grid of scatter plots for every pair of variables', 'It allows exploratory analysis of multi-dimensional relationships.', 'active'),
('60000000-0000-0000-0000-000000000203', '50000000-0000-0000-0000-000000000016', 'intermediate', 'code_mcq', 'How do you plot a distribution with a kernel density estimate in Seaborn?', '["sns.histplot(kde=True)", "sns.lineplot()", "sns.barplot()", "plt.plot()"]', 'sns.histplot(kde=True)', 'KDE provides a smoothed version of the histogram.', 'active'),
('60000000-0000-0000-0000-000000000204', '50000000-0000-0000-0000-000000000016', 'expert', 'mcq', 'What is Plotly primarily known for?', '["Interactive web-based visualizations", "Static printing only", "Binary file encryption", "Deep learning training"]', 'Interactive web-based visualizations', 'Plotly allows zooming, hovering, and filtering directly in the browser.', 'active'),
('60000000-0000-0000-0000-000000000205', '50000000-0000-0000-0000-000000000016', 'expert', 'code_mcq', 'How do you create a 3D scatter plot in Plotly Express?', '["px.scatter_3d()", "px.scatter(3d=True)", "plt.scatter3d()", "sns.3d_scatter()"]', 'px.scatter_3d()', 'It allows plotting points in an x, y, z coordinate system.', 'active'),
('60000000-0000-0000-0000-000000000206', '50000000-0000-0000-0000-000000000016', 'expert', 'mcq', 'Which Python library helps build interactive data dashboards?', '["Dash or Streamlit", "PyGame", "BeautifulSoup", "NumPy"]', 'Dash or Streamlit', 'These frameworks turn data scripts into shareable web apps easily.', 'active'),
('60000000-0000-0000-0000-000000000207', '50000000-0000-0000-0000-000000000016', 'expert', 'code_mcq', 'What is the purpose of st.write() in Streamlit?', '["Magic command to display almost any object", "Writes data to a CSV file", "Opens a write stream to database", "Clears the dashboard"]', 'Magic command to display almost any object', 'It handles text, dataframes, charts, and more automatically.', 'active'),
('60000000-0000-0000-0000-000000000208', '50000000-0000-0000-0000-000000000016', 'expert', 'mcq', 'What does the term "Data Ink Ratio" refer to?', '["The proportion of ink used for actual data vs non-data elements", "The amount of data per pixel", "The brightness of the chart", "The resolution of the output file"]', 'The proportion of ink used for actual data vs non-data elements', 'Edward Tufte coined this to encourage simplicity and clarity in charts.', 'active')
