INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000000209', '50000000-0000-0000-0000-000000000017', 'simple', 'mcq', 'What is AWS EC2?', '["Virtual servers in the cloud", "Managed database service", "Content delivery network", "Storage service"]', 'Virtual servers in the cloud', 'EC2 (Elastic Compute Cloud) provides resizable compute capacity.', 'active'),
('60000000-0000-0000-0000-000000000210', '50000000-0000-0000-0000-000000000017', 'simple', 'mcq', 'What is Amazon S3 primarily used for?', '["Object storage", "Running code", "Relational databases", "DNS management"]', 'Object storage', 'S3 (Simple Storage Service) is built to store and retrieve any amount of data.', 'active'),
('60000000-0000-0000-0000-000000000211', '50000000-0000-0000-0000-000000000017', 'simple', 'mcq', 'What is AWS Lambda?', '["Serverless compute service", "Virtual machine", "Managed container service", "Database engine"]', 'Serverless compute service', 'Lambda let you run code without provisioning or managing servers.', 'active'),
('60000000-0000-0000-0000-000000000212', '50000000-0000-0000-0000-000000000017', 'simple', 'mcq', 'What does EBS stand for in AWS?', '["Elastic Block Store", "Elastic backup System", "Easy Block Storage", "Elastic Base Server"]', 'Elastic Block Store', 'EBS provides block level storage volumes for use with EC2 instances.', 'active'),
('60000000-0000-0000-0000-000000000213', '50000000-0000-0000-0000-000000000017', 'intermediate', 'mcq', 'Which EC2 pricing model is best for long-term, stable workloads?', '["Reserved Instances", "On-Demand", "Spot Instances", "Dedicated Hosts"]', 'Reserved Instances', 'Reserved Instances provide significant discounts compared to On-Demand.', 'active'),
('60000000-0000-0000-0000-000000000214', '50000000-0000-0000-0000-000000000017', 'intermediate', 'mcq', 'What is S3 Transfer Acceleration?', '["Enables fast file transfers over long distances using CloudFront", "Increases EC2 bandwidth", "Speeds up database queries", "Speeds up EBS snapshots"]', 'Enables fast file transfers over long distances using CloudFront', 'It uses CloudFront''s globally distributed edge locations.', 'active'),
('60000000-0000-0000-0000-000000000215', '50000000-0000-0000-0000-000000000017', 'intermediate', 'mcq', 'What is the purpose of Auto Scaling?', '["Automatically adjust capacity to maintain steady performance", "Back up data", "Monitor logs", "Distribute traffic"]', 'Automatically adjust capacity to maintain steady performance', 'Auto Scaling adds or removes EC2 instances based on demand.', 'active'),
('60000000-0000-0000-0000-000000000216', '50000000-0000-0000-0000-000000000017', 'intermediate', 'mcq', 'What is an Amazon Machine Image (AMI)?', '["A template that contains software configuration", "A physical server", "A database backup", "A networking protocol"]', 'A template that contains software configuration', 'An AMI provides the information required to launch an instance.', 'active'),
('60000000-0000-0000-0000-000000000217', '50000000-0000-0000-0000-000000000017', 'expert', 'mcq', 'What is AWS Glacier used for?', '["Long-term data archiving", "Low-latency database", "High-performance compute", "Real-time streaming"]', 'Long-term data archiving', 'Glacier is extremely low-cost storage service for data archiving and long-term backup.', 'active'),
('60000000-0000-0000-0000-000000000218', '50000000-0000-0000-0000-000000000017', 'expert', 'mcq', 'What is the "Placement Group" in EC2?', '["Determines how instances are placed on hardware", "A logical group of users", "A storage backup group", "A networking subnet"]', 'Determines how instances are placed on hardware', 'Placement groups help achieve lower latency or higher availability.', 'active'),
('60000000-0000-0000-0000-000000000219', '50000000-0000-0000-0000-000000000017', 'expert', 'mcq', 'What is Instance Store storage?', '["Temporary block-level storage for an instance", "Persistent storage for an instance", "Cloud-based database", "Shared file system"]', 'Temporary block-level storage for an instance', 'Instance Store data is lost if the instance is stopped or terminated.', 'active'),
('60000000-0000-0000-0000-000000000220', '50000000-0000-0000-0000-000000000017', 'expert', 'mcq', 'In S3, what is "strong read-after-write consistency"?', '["Immediate availability of data after a write", "Eventual availability", "No availability guarantee", "Backup consistency only"]', 'Immediate availability of data after a write', 'AWS S3 now provides strong read-after-write consistency for all objects.', 'active'),
('60000000-0000-0000-0000-000000000221', '50000000-0000-0000-0000-000000000017', 'expert', 'mcq', 'What is AWS EFS?', '["Elastic File System for Linux workloads", "Managed database service", "Block storage service", "Object storage service"]', 'Elastic File System for Linux workloads', 'EFS provides a simple, scalable, fully managed elastic NFS file system.', 'active')
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000000222', '50000000-0000-0000-0000-000000000018', 'simple', 'mcq', 'What is Amazon VPC?', '["Virtual Private Cloud", "Virtual Public Cloud", "Visible Private Cloud", "Virtual Proxy Control"]', 'Virtual Private Cloud', 'VPC lets you provision a logically isolated section of the AWS Cloud.', 'active'),
('60000000-0000-0000-0000-000000000223', '50000000-0000-0000-0000-000000000018', 'simple', 'mcq', 'What is Amazon RDS?', '["Managed Relational Database Service", "Remote Data System", "Real-time Data Storage", "Reliable Database Service"]', 'Managed Relational Database Service', 'RDS makes it easy to set up, operate, and scale relational databases.', 'active'),
('60000000-0000-0000-0000-000000000224', '50000000-0000-0000-0000-000000000018', 'simple', 'mcq', 'What is AWS Route 53?', '["Scalable Domain Name System (DNS)", "Managed route controller", "Port 53 firewall", "VPN gateway"]', 'Scalable Domain Name System (DNS)', 'Route 53 is a highly available and scalable cloud DNS web service.', 'active'),
('60000000-0000-0000-0000-000000000225', '50000000-0000-0000-0000-000000000018', 'simple', 'mcq', 'What is Amazon DynamoDB?', '["NoSQL database service", "Relational database", "Graph database", "Data warehouse"]', 'NoSQL database service', 'DynamoDB is a fully managed NoSQL database service.', 'active'),
('60000000-0000-0000-0000-000000000226', '50000000-0000-0000-0000-000000000018', 'intermediate', 'mcq', 'What is an Internet Gateway (IGW) in VPC?', '["A gateway connecting a VPC to the internet", "A private connection to AWS VPC", "A firewall for EC2", "A database sync tool"]', 'A gateway connecting a VPC to the internet', 'An IGW allows communication between your VPC and the internet.', 'active'),
('60000000-0000-0000-0000-000000000227', '50000000-0000-0000-0000-000000000018', 'intermediate', 'mcq', 'What is VPC Peering?', '["Networking connection between two VPCs", "Connecting VPC to on-premises", "Connecting VPC to internet", "Backing up VPC data"]', 'Networking connection between two VPCs', 'VPC peering allows routing traffic between VPCs using private IP addresses.', 'active'),
('60000000-0000-0000-0000-000000000228', '50000000-0000-0000-0000-000000000018', 'intermediate', 'mcq', 'What is Amazon ElastiCache?', '["Managed in-memory cache service", "Managed storage service", "Managed database service", "Managed CDN"]', 'Managed in-memory cache service', 'It supports Redis and Memcached for improving web application performance.', 'active'),
('60000000-0000-0000-0000-000000000229', '50000000-0000-0000-0000-000000000018', 'intermediate', 'mcq', 'What is Aurora in AWS RDS?', '["AWS-native MySQL and PostgreSQL compatible database", "Managed MongoDB", "Graph database", "Managed Cassandra"]', 'AWS-native MySQL and PostgreSQL compatible database', 'Aurora is up to 5 times faster than standard MySQL.', 'active'),
('60000000-0000-0000-0000-000000000230', '50000000-0000-0000-0000-000000000018', 'expert', 'mcq', 'What is AWS Direct Connect?', '["Dedicated network connection from on-premises to AWS", "VPN connection", "Public internet connection", "Multi-AZ VPC"]', 'Dedicated network connection from on-premises to AWS', 'It provides a more consistent network experience than internet-based connections.', 'active'),
('60000000-0000-0000-0000-000000000231', '50000000-0000-0000-0000-000000000018', 'expert', 'mcq', 'What is a Transit Gateway?', '["Connects VPCs and on-premises networks through a central hub", "Connects two VPCs only", "Connects VPC to internet only", "Managed firewall"]', 'Connects VPCs and on-premises networks through a central hub', 'It simplifies network topology and reduces management complexity.', 'active'),
('60000000-0000-0000-0000-000000000232', '50000000-0000-0000-0000-000000000018', 'expert', 'mcq', 'What is Amazon Redshift?', '["Cloud data warehouse", "Managed NoSQL database", "In-memory database", "Graph database"]', 'Cloud data warehouse', 'Redshift uses SQL to analyze structured and semi-structured data.', 'active'),
('60000000-0000-0000-0000-000000000233', '50000000-0000-0000-0000-000000000018', 'expert', 'mcq', 'What is the "Global Table" feature in DynamoDB?', '["Multi-region, multi-active database", "Backup for global access", "Read-only global replicas", "Table size up to 1PB"]', 'Multi-region, multi-active database', 'Global Tables replicate DynamoDB data automatically across AWS Regions.', 'active'),
('60000000-0000-0000-0000-000000000234', '50000000-0000-0000-0000-000000000018', 'expert', 'mcq', 'What is AWS PrivateLink?', '["Connects VPCs to AWS services privately", "Public peering", "Mobile VPN", "Encryption tool"]', 'Connects VPCs to AWS services privately', 'Traffic stays on the AWS network and doesn''t traverse the public internet.', 'active')
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000000235', '50000000-0000-0000-0000-000000000019', 'simple', 'mcq', 'What is Microsoft Azure?', '["Public cloud computing platform", "Managed database service", "Desktop OS", "Browser extension"]', 'Public cloud computing platform', 'Azure provides services for computing, analytics, storage, and networking.', 'active'),
('60000000-0000-0000-0000-000000000236', '50000000-0000-0000-0000-000000000019', 'simple', 'mcq', 'What is Azure Virtual Machines?', '["On-demand scalable computing resources", "Managed containers", "Serverless functions", "Database service"]', 'On-demand scalable computing resources', 'Azure VMs are the infrastructure as a service (IaaS) offering from Microsoft.', 'active'),
('60000000-0000-0000-0000-000000000237', '50000000-0000-0000-0000-000000000019', 'simple', 'mcq', 'What is Azure Blob Storage?', '["Object storage for unstructured data", "Relational database", "Block storage for VMs", "NoSQL database"]', 'Object storage for unstructured data', 'Storage that is optimized for storing massive amounts of unstructured data.', 'active'),
('60000000-0000-0000-0000-000000000238', '50000000-0000-0000-0000-000000000019', 'simple', 'mcq', 'What is Azure Active Directory (Azure AD)?', '["Identity and access management service", "Database manager", "Virtual network", "Server monitoring tool"]', 'Identity and access management service', 'Azure AD (now Entra ID) helps users sign in and access resources.', 'active'),
('60000000-0000-0000-0000-000000000239', '50000000-0000-0000-0000-000000000019', 'intermediate', 'mcq', 'What is Azure Resource Manager (ARM)?', '["Deployment and management service for Azure", "Compute instance manager", "Database backup tool", "Network monitor"]', 'Deployment and management service for Azure', 'ARM is the management layer that allows you to create, update, and delete resources.', 'active'),
('60000000-0000-0000-0000-000000000240', '50000000-0000-0000-0000-000000000019', 'intermediate', 'mcq', 'What is Azure SQL Database?', '["Managed relational database service", "Managed NoSQL database", "On-premises SQL server", "Flat file storage"]', 'Managed relational database service', 'A fully-managed platform as a service (PaaS) database engine.', 'active'),
('60000000-0000-0000-0000-000000000241', '50000000-0000-0000-0000-000000000019', 'intermediate', 'mcq', 'What is Azure App Service?', '["HTTP-based service for hosting web applications", "Mobile app builder", "Database manager", "Network gateway"]', 'HTTP-based service for hosting web applications', 'It is a PaaS that supports building web, mobile, and API apps.', 'active'),
('60000000-0000-0000-0000-000000000242', '50000000-0000-0000-0000-000000000019', 'intermediate', 'mcq', 'What is Azure Functions?', '["Serverless compute service", "Managed containers", "Virtual machine", "Database engine"]', 'Serverless compute service', 'Azure Functions allows you to run small pieces of code (functions) without worrying about infrastructure.', 'active'),
('60000000-0000-0000-0000-000000000243', '50000000-0000-0000-0000-000000000019', 'expert', 'mcq', 'What is Azure Cosmos DB?', '["Globally distributed, multi-model NoSQL database", "Relational database for big data", "Graph database only", "Managed Redis instance"]', 'Globally distributed, multi-model NoSQL database', 'Cosmos DB provides low-latency access to data with flexible schema.', 'active'),
('60000000-0000-0000-0000-000000000244', '50000000-0000-0000-0000-000000000019', 'expert', 'mcq', 'What is Azure Kubernetes Service (AKS)?', '["Managed Kubernetes container orchestration", "Managed Docker swarm", "Virtual server service", "Cloud-native database"]', 'Managed Kubernetes container orchestration', 'AKS simplifies deploying, managing, and scaling Kubernetes in Azure.', 'active'),
('60000000-0000-0000-0000-000000000245', '50000000-0000-0000-0000-000000000019', 'expert', 'mcq', 'What is Azure ExpressRoute?', '["Private network connection between on-premises and Azure", "Managed VPN gateway", "Public internet path", "Multi-region replication service"]', 'Private network connection between on-premises and Azure', 'Traffic over ExpressRoute does not traverse the public internet.', 'active'),
('60000000-0000-0000-0000-000000000246', '50000000-0000-0000-0000-000000000019', 'expert', 'mcq', 'What is the purpose of Azure Key Vault?', '["Securely store and access secrets", "Store virtual machine images", "Backup database logs", "Monitor network routes"]', 'Securely store and access secrets', 'It helps protect cryptographic keys and secrets used by cloud apps.', 'active'),
('60000000-0000-0000-0000-000000000247', '50000000-0000-0000-0000-000000000019', 'expert', 'mcq', 'What is Azure DevOps?', '["Suite of services for managing software lifecycle", "A single tool for CI/CD", "Managed Kubernetes service", "Monitoring tool"]', 'Suite of services for managing software lifecycle', 'Azure DevOps includes boards, repos, pipelines, test plans, and artifacts.', 'active')
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000000248', '50000000-0000-0000-0000-000000000020', 'simple', 'mcq', 'What is Google Cloud Platform (GCP)?', '["Public cloud service from Google", "Google''s search engine", "Google Workspace", "Chrome browser engine"]', 'Public cloud service from Google', 'GCP offers a suite of cloud computing services that run on the same infrastructure as Google products.', 'active'),
('60000000-0000-0000-0000-000000000249', '50000000-0000-0000-0000-000000000020', 'simple', 'mcq', 'What is Compute Engine in GCP?', '["Scalable virtual machine service", "Serverless function service", "Managed container service", "Managed database service"]', 'Scalable virtual machine service', 'Compute Engine provides VMs that run on Google''s infrastructure.', 'active'),
('60000000-0000-0000-0000-000000000250', '50000000-0000-0000-0000-000000000020', 'simple', 'mcq', 'What is Cloud Storage in GCP?', '["Unified object storage service", "Relational database", "Block storage for VMs", "NoSQL database"]', 'Unified object storage service', 'Cloud Storage is for unstructured data with varying access frequencies.', 'active'),
('60000000-0000-0000-0000-000000000251', '50000000-0000-0000-0000-000000000020', 'simple', 'mcq', 'What is BigQuery?', '["Serverless enterprise data warehouse", "Managed SQL database", "NoSQL database", "Storage system"]', 'Serverless enterprise data warehouse', 'BigQuery is for large-scale data analysis using SQL.', 'active'),
('60000000-0000-0000-0000-000000000252', '50000000-0000-0000-0000-000000000020', 'intermediate', 'mcq', 'What is Google Kubernetes Engine (GKE)?', '["Managed Kubernetes service", "Managed Docker swarm", "Serverless containers", "Virtual machine group"]', 'Managed Kubernetes service', 'GKE provides a managed environment for deploying and managing containerized apps.', 'active'),
('60000000-0000-0000-0000-000000000253', '50000000-0000-0000-0000-000000000020', 'intermediate', 'mcq', 'What is Cloud SQL?', '["Managed relational database service for MySQL/PostgreSQL/SQL Server", "NoSQL database", "Database backup tool", "Graph database"]', 'Managed relational database service for MySQL/PostgreSQL/SQL Server', 'Cloud SQL makes it easy to set up and manage relational databases on GCP.', 'active'),
('60000000-0000-0000-0000-000000000254', '50000000-0000-0000-0000-000000000020', 'intermediate', 'mcq', 'What is Cloud Functions?', '["Serverless execution environment for building and connecting cloud services", "Managed VMs", "Managed containers", "Database trigger service"]', 'Serverless execution environment for building and connecting cloud services', 'Cloud Functions allows you to run code in response to events.', 'active'),
('60000000-0000-0000-0000-000000000255', '50000000-0000-0000-0000-000000000020', 'intermediate', 'mcq', 'What is VPC in GCP?', '["Virtual Private Cloud", "Virtual Public Cloud", "Visible Private Cloud", "Network controller"]', 'Virtual Private Cloud', 'VPC provides networking functionality to GCP resources.', 'active'),
('60000000-0000-0000-0000-000000000256', '50000000-0000-0000-0000-000000000020', 'expert', 'mcq', 'What is Cloud Spanner?', '["Fully managed, horizontally scalable, relational database", "NoSQL database", "Graph database", "In-memory database"]', 'Fully managed, horizontally scalable, relational database', 'Spanner provides strong consistency and global scalability.', 'active'),
('60000000-0000-0000-0000-000000000257', '50000000-0000-0000-0000-000000000020', 'expert', 'mcq', 'What is Cloud Pub/Sub?', '["Asynchronous messaging service", "Managed database", "Storage service", "Network gateway"]', 'Asynchronous messaging service', 'Pub/Sub is used for stream analytics and data integration pipelines.', 'active'),
('60000000-0000-0000-0000-000000000258', '50000000-0000-0000-0000-000000000020', 'expert', 'mcq', 'What is Cloud Armor?', '["Network security service for WAF and DDoS protection", "Identity management", "Resource monitor", "Encryption service"]', 'Network security service for WAF and DDoS protection', 'Cloud Armor helps protect your applications and websites from attacks.', 'active'),
('60000000-0000-0000-0000-000000000259', '50000000-0000-0000-0000-000000000020', 'expert', 'mcq', 'What is Cloud Run?', '["Managed compute platform for running containerized apps", "Serverless functions only", "Managed VMs only", "Managed Kubernetes service"]', 'Managed compute platform for running containerized apps', 'Cloud Run is a serverless platform that automatically scales your containers.', 'active'),
('60000000-0000-0000-0000-000000000260', '50000000-0000-0000-0000-000000000020', 'expert', 'mcq', 'What is Identity-Aware Proxy (IAP)?', '["Controls access to cloud apps based on identity and context", "Managed VPN gateway", "Firewall service", "DNS manager"]', 'Controls access to cloud apps based on identity and context', 'IAP allows you to enforce centralized access control policies.', 'active')
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000000261', '50000000-0000-0000-0000-000000000021', 'simple', 'mcq', 'What is Docker?', '["Software platform for building and running containers", "A virtual machine manager", "A database engine", "A web server"]', 'Software platform for building and running containers', 'Docker simplifies the process of creating, deploying, and running applications by using containers.', 'active'),
('60000000-0000-0000-0000-000000000262', '50000000-0000-0000-0000-000000000021', 'simple', 'mcq', 'What is a Docker image?', '["A read-only template for creating a container", "A running container", "A network configuration", "A storage volume"]', 'A read-only template for creating a container', 'An image includes everything needed to run an application.', 'active'),
('60000000-0000-0000-0000-000000000263', '50000000-0000-0000-0000-000000000021', 'simple', 'mcq', 'What is a Dockerfile?', '["A text document containing instructions to build an image", "A running container instance", "A network definition file", "A storage mount point"]', 'A text document containing instructions to build an image', 'A Dockerfile consists of various commands and arguments used to create a Docker image.', 'active'),
('60000000-0000-0000-0000-000000000264', '50000000-0000-0000-0000-000000000021', 'simple', 'code_mcq', 'What command builds an image from a Dockerfile?', '["docker build", "docker build-image", "docker create", "docker run"]', 'docker build', 'The docker build command builds images from a Dockerfile and a "context".', 'active'),
('60000000-0000-0000-0000-000000000265', '50000000-0000-0000-0000-000000000021', 'intermediate', 'mcq', 'What is a container?', '["A runnable instance of an image", "A static file", "A virtual machine", "A database table"]', 'A runnable instance of an image', 'Containers are isolated from each other and the host system.', 'active'),
('60000000-0000-0000-0000-000000000266', '50000000-0000-0000-0000-000000000021', 'intermediate', 'code_mcq', 'What does the -p flag in docker run do?', '["Publishes a container''s port to the host", "Sets container password", "Allocates a pseudo-TTY", "Defines partition size"]', 'Publishes a container''s port to the host', 'It maps host ports to container ports.', 'active'),
('60000000-0000-0000-0000-000000000267', '50000000-0000-0000-0000-000000000021', 'intermediate', 'mcq', 'What is Docker Hub?', '["A cloud-based registry for Docker images", "A local image manager", "A container orchestration tool", "A networking dashboard"]', 'A cloud-based registry for Docker images', 'Docker Hub is the world’s largest library and community for container images.', 'active'),
('60000000-0000-0000-0000-000000000268', '50000000-0000-0000-0000-000000000021', 'intermediate', 'code_mcq', 'What is the purpose of docker-compose?', '["Defining and running multi-container Docker applications", "Building single images", "Pushing images to registry", "Debugging containers"]', 'Defining and running multi-container Docker applications', 'Compose uses a YAML file to configure application services.', 'active'),
('60000000-0000-0000-0000-000000000269', '50000000-0000-0000-0000-000000000021', 'expert', 'mcq', 'What is a "multi-stage build" in Docker?', '["Using multiple FROM instructions to optimize image size", "Building multiple images simultaneously", "Building images in different environments", "Using multiple Dockerfiles"]', 'Using multiple FROM instructions to optimize image size', 'Multi-stage builds allow smaller, more efficient final images.', 'active'),
('60000000-0000-0000-0000-000000000270', '50000000-0000-0000-0000-000000000021', 'expert', 'code_mcq', 'What is the purpose of the CMD instruction?', '["Specifying the default command to run when the container starts", "Building the image", "Mounting volumes", "Defining build-time variables"]', 'Specifying the default command to run when the container starts', 'CMD is used to provide defaults for an executing container.', 'active'),
('60000000-0000-0000-0000-000000000271', '50000000-0000-0000-0000-000000000021', 'expert', 'mcq', 'What is a Docker Volume?', '["Mechanisms for persisting data generated by and used by containers", "A network drive", "A virtual disk image", "A database partition"]', 'Mechanisms for persisting data generated by and used by containers', 'Volumes are preferred over bind mounts for persistence.', 'active'),
('60000000-0000-0000-0000-000000000272', '50000000-0000-0000-0000-000000000021', 'expert', 'code_mcq', 'What does docker exec -it [container_id] bash do?', '["Starts an interactive bash session inside a running container", "Starts a new container with bash", "Builds a container using bash", "Terminates a container with bash"]', 'Starts an interactive bash session inside a running container', 'It allows running commands inside a container that is already active.', 'active'),
('60000000-0000-0000-0000-000000000273', '50000000-0000-0000-0000-000000000021', 'expert', 'mcq', 'What is the difference between a container and a VM?', '["Containers share the host OS kernel; VMs have their own", "VMs are lighter than containers", "Containers use more resources", "VMs don''t have a kernel"]', 'Containers share the host OS kernel; VMs have their own', 'Containers are much more lightweight and faster to start.', 'active')
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000000274', '50000000-0000-0000-0000-000000000022', 'simple', 'mcq', 'What is Kubernetes?', '["Open-source system for automating deployment and scaling of containers", "Managed database service", "Virtual machine monitor", "Programming language"]', 'Open-source system for automating deployment and scaling of containers', 'Kubernetes (K8s) is the industry standard for container orchestration.', 'active'),
('60000000-0000-0000-0000-000000000275', '50000000-0000-0000-0000-000000000022', 'simple', 'mcq', 'What is a Pod in Kubernetes?', '["The smallest deployable unit that can be created and managed", "A single container only", "A group of virtual machines", "A storage volume"]', 'The smallest deployable unit that can be created and managed', 'A Pod can contain one or more containers that share storage and network.', 'active'),
('60000000-0000-0000-0000-000000000276', '50000000-0000-0000-0000-000000000022', 'simple', 'mcq', 'What is kubectl?', '["Command-line tool for controlling Kubernetes clusters", "Kubernetes server component", "Container runtime", "YAML validator"]', 'Command-line tool for controlling Kubernetes clusters', 'It is the primary interface for interacting with the K8s API.', 'active'),
('60000000-0000-0000-0000-000000000277', '50000000-0000-0000-0000-000000000022', 'simple', 'code_mcq', 'What command shows all running pods?', '["kubectl get pods", "kubectl list pods", "kubectl describe pods", "kubectl show pods"]', 'kubectl get pods', 'The get command is used to list various Kubernetes resources.', 'active'),
('60000000-0000-0000-0000-000000000278', '50000000-0000-0000-0000-000000000022', 'intermediate', 'mcq', 'What is a ReplicaSet?', '["Maintains a stable set of replica Pods running at any given time", "A backup of a database", "A cluster of nodes", "A network policy"]', 'Maintains a stable set of replica Pods running at any given time', 'It ensures that a specified number of pod replicas are running.', 'active'),
('60000000-0000-0000-0000-000000000279', '50000000-0000-0000-0000-000000000022', 'intermediate', 'mcq', 'What is a Service in Kubernetes?', '["Abstract way to expose an application running on a set of Pods", "A background cron job", "A system update", "A hardware node"]', 'Abstract way to expose an application running on a set of Pods', 'Services provide a single point of entry to a group of pods.', 'active'),
('60000000-0000-0000-0000-000000000280', '50000000-0000-0000-0000-000000000022', 'intermediate', 'mcq', 'What is a Deployment?', '["Declarative update for Pods and ReplicaSets", "Physical server setup", "Database migration tool", "Network firewall"]', 'Declarative update for Pods and ReplicaSets', 'Deployments allow you to describe an application''s life cycle.', 'active'),
('60000000-0000-0000-0000-000000000281', '50000000-0000-0000-0000-000000000022', 'intermediate', 'code_mcq', 'What does "nodePort" do in a Service definition?', '["Exposes the service on each Node''s IP at a static port", "Sets the internal cluster IP", "Limits traffic to a specific node", "Defines the pod port"]', 'Exposes the service on each Node''s IP at a static port', 'It makes the service accessible from outside the cluster by using the node''s IP.', 'active'),
('60000000-0000-0000-0000-000000000282', '50000000-0000-0000-0000-000000000022', 'expert', 'mcq', 'What is the purpose of the Control Plane?', '["Coordinates all activities in the cluster", "Runs application containers", "Stores application data", "Handles external traffic only"]', 'Coordinates all activities in the cluster', 'The Control Plane manages nodes and pods in the cluster.', 'active'),
('60000000-0000-0000-0000-000000000283', '50000000-0000-0000-0000-000000000022', 'expert', 'mcq', 'What is Helm?', '["Package manager for Kubernetes", "Kubernetes monitoring tool", "Log aggregator", "Kernel module"]', 'Package manager for Kubernetes', 'Helm uses "Charts" to define, install, and upgrade applications.', 'active'),
('60000000-0000-0000-0000-000000000284', '50000000-0000-0000-0000-000000000022', 'expert', 'mcq', 'What is an Ingress Controller?', '["Managed load balancer for external access to services", "A pod that fails", "A database connector", "An internal network bridge"]', 'Managed load balancer for external access to services', 'It typically provides HTTP and HTTPS routing to services.', 'active'),
('60000000-0000-0000-0000-000000000285', '50000000-0000-0000-0000-000000000022', 'expert', 'mcq', 'What is ETCD in Kubernetes context?', '["Consistent and highly-available key-value store for cluster data", "Container engine", "Network plugin", "Scheduler backend"]', 'Consistent and highly-available key-value store for cluster data', 'ETCD stores the configuration data of the Kubernetes cluster.', 'active'),
('60000000-0000-0000-0000-000000000286', '50000000-0000-0000-0000-000000000022', 'expert', 'mcq', 'What is the difference between StatefulSet and Deployment?', '["StatefulSet maintains a sticky identity for each pod", "Deployment is only for databases", "StatefulSet doesn''t support replicas", "Deployments are newer"]', 'StatefulSet maintains a sticky identity for each pod', 'StatefulSets are valuable for applications that require unique identifies or persistent storage.', 'active')
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000000287', '50000000-0000-0000-0000-000000000023', 'simple', 'mcq', 'What is the main characteristic of serverless computing?', '["Developer doesn''t manage servers", "Servers are physically removed", "Applications run without code", "No cost is involved"]', 'Developer doesn''t manage servers', 'The cloud provider automatically manages the infrastructure.', 'active'),
('60000000-0000-0000-0000-000000000288', '50000000-0000-0000-0000-000000000023', 'simple', 'mcq', 'Which of these is a serverless offering?', '["AWS Lambda", "EC2 m5.large", "Physical rack", "Bare metal server"]', 'AWS Lambda', 'AWS Lambda is a flagship serverless Compute service.', 'active'),
('60000000-0000-0000-0000-000000000289', '50000000-0000-0000-0000-000000000023', 'simple', 'mcq', 'What is FaaS?', '["Function as a Service", "Feature as a Service", "Fast as a Service", "File as a Service"]', 'Function as a Service', 'FaaS is a category of cloud computing services that provides a platform for customers to develop, run, and manage application functionalities.', 'active'),
('60000000-0000-0000-0000-000000000290', '50000000-0000-0000-0000-000000000023', 'simple', 'mcq', 'What is the "pay-as-you-go" model?', '["Paying only for what you consume", "Fixed monthly fee", "Annual subscription", "Free for everyone"]', 'Paying only for what you consume', 'In serverless, you only pay for the execution time and resources used.', 'active'),
('60000000-0000-0000-0000-000000000291', '50000000-0000-0000-0000-000000000023', 'intermediate', 'mcq', 'What is "Cold Start" in serverless?', '["The latency when an idle function is triggered", "Starting a server in a cold room", "A system crash", "Updating a function"]', 'The latency when an idle function is triggered', 'A cold start occurs when a function is invoked after not being used for a while.', 'active'),
('60000000-0000-0000-0000-000000000292', '50000000-0000-0000-0000-000000000023', 'intermediate', 'mcq', 'Which event can trigger a serverless function?', '["HTTP request, Database change, File upload", "Only HTTP requests", "Only manual clicks", "System reboots only"]', 'HTTP request, Database change, File upload', 'Serverless functions are typically event-driven.', 'active'),
('60000000-0000-0000-0000-000000000293', '50000000-0000-0000-0000-000000000023', 'intermediate', 'mcq', 'What is the purpose of API Gateway in a serverless setup?', '["Handles application entry point and routing", "Stores database records", "Executes background jobs", "Provides storage space"]', 'Handles application entry point and routing', 'API Gateway acts as the "front door" for applications.', 'active'),
('60000000-0000-0000-0000-000000000294', '50000000-0000-0000-0000-000000000023', 'intermediate', 'mcq', 'What is a stateless function?', '["A function that doesn''t store client data locally between calls", "A function with no code", "A function that never runs", "A secure function"]', 'A function that doesn''t store client data locally between calls', 'Serverless functions should be stateless to allow for scaling.', 'active'),
('60000000-0000-0000-0000-000000000295', '50000000-0000-0000-0000-000000000023', 'expert', 'mcq', 'How can you mitigate cold starts?', '["Provisioned concurrency or keep-warm pings", "Upgrading the CPU", "Changing the language", "Increasing function timeout"]', 'Provisioned concurrency or keep-warm pings', 'Provisioned concurrency keeps functions initialized and ready to respond.', 'active'),
('60000000-0000-0000-0000-000000000296', '50000000-0000-0000-0000-000000000023', 'expert', 'mcq', 'What is the "Serverless Framework"?', '["CLI tool for multi-cloud serverless development", "The AWS management console", "A type of database", "A serverless runtime"]', 'CLI tool for multi-cloud serverless development', 'It helps deploy and manage serverless applications on various providers.', 'active'),
('60000000-0000-0000-0000-000000000297', '50000000-0000-0000-0000-000000000023', 'expert', 'mcq', 'What is a "Durable Function"?', '["A stateful function extension in Azure", "A function that lasts forever", "A function with infinite memory", "A secure function"]', 'A stateful function extension in Azure', 'Durable Functions allow writing stateful functions in a serverless environment.', 'active'),
('60000000-0000-0000-0000-000000000298', '50000000-0000-0000-0000-000000000023', 'expert', 'mcq', 'What is Step Functions in AWS?', '["Visual workflow orchestrator for serverless apps", "Managed container service", "Database migration tool", "Monitoring system"]', 'Visual workflow orchestrator for serverless apps', 'Step Functions lets you build complex workflows by connecting multiple AWS services.', 'active'),
('60000000-0000-0000-0000-000000000299', '50000000-0000-0000-0000-000000000023', 'expert', 'mcq', 'What is "BaaS"?', '["Backend as a Service", "Database as a Service", "Binary as a Service", "Backup as a Service"]', 'Backend as a Service', 'BaaS provides backend services like authentication and database as managed cloud APIs.', 'active')
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000000300', '50000000-0000-0000-0000-000000000024', 'simple', 'mcq', 'What is Infrastructure as Code (IaC)?', '["Managing infrastructure through code files", "Coding websites", "Running hardware diagnostic code", "Coding in the cloud only"]', 'Managing infrastructure through code files', 'IaC allows for consistent and repeatable infrastructure deployments.', 'active'),
('60000000-0000-0000-0000-000000000301', '50000000-0000-0000-0000-000000000024', 'simple', 'mcq', 'What is Terraform?', '["An open-source IaC tool from HashiCorp", "A database engine", "A virtual machine manager", "A cloud provider"]', 'An open-source IaC tool from HashiCorp', 'Terraform uses HCL (HashiCorp Configuration Language) to define resources.', 'active'),
('60000000-0000-0000-0000-000000000302', '50000000-0000-0000-0000-000000000024', 'simple', 'mcq', 'What is AWS CloudFormation?', '["Managed IaC service for AWS", "AWS monitoring tool", "AWS storage service", "AWS security service"]', 'Managed IaC service for AWS', 'CloudFormation allows you to use JSON or YAML templates to model and provision AWS resources.', 'active'),
('60000000-0000-0000-0000-000000000303', '50000000-0000-0000-0000-000000000024', 'simple', 'code_mcq', 'What does "terraform init" do?', '["Initializes a working directory containing configuration files", "Executes the code", "Deletes resources", "Previews changes"]', 'Initializes a working directory containing configuration files', 'It downloads providers and modules required for the configuration.', 'active'),
('60000000-0000-0000-0000-000000000304', '50000000-0000-0000-0000-000000000024', 'intermediate', 'mcq', 'What is the "State File" in Terraform?', '["A file that tracks current infrastructure state", "A list of cloud providers", "An instruction manual", "A temporary log file"]', 'A file that tracks current infrastructure state', 'The state file is used to map real-world resources to your configuration.', 'active'),
('60000000-0000-0000-0000-000000000305', '50000000-0000-0000-0000-000000000024', 'intermediate', 'code_mcq', 'What command shows the summary of changes before applying in Terraform?', '["terraform plan", "terraform show", "terraform diff", "terraform preview"]', 'terraform plan', 'The plan command lets you see what Terraform will do before making actual changes.', 'active'),
('60000000-0000-0000-0000-000000000306', '50000000-0000-0000-0000-000000000024', 'intermediate', 'mcq', 'What is an "Idempotent" operation in IaC?', '["An operation that produces the same result regardless of how many times it''s run", "An operation that only runs once", "A fast operation", "A secure operation"]', 'An operation that produces the same result regardless of how many times it''s run', 'Idempotency ensures consistency in infrastructure state.', 'active'),
('60000000-0000-0000-0000-000000000307', '50000000-0000-0000-0000-000000000024', 'intermediate', 'mcq', 'What is Ansible primarily used for?', '["Configuration management and application deployment", "Provisioning virtual machines only", "Storing secrets", "Monitoring networks"]', 'Configuration management and application deployment', 'Ansible is an agentless automation tool using YAML playbooks.', 'active'),
('60000000-0000-0000-0000-000000000308', '50000000-0000-0000-0000-000000000024', 'expert', 'mcq', 'What are Terraform Modules?', '["Containers for multiple resources used together", "Managed plugins", "Individual resources only", "Cloud provider regions"]', 'Containers for multiple resources used together', 'Modules allow for reusable and organized infrastructure patterns.', 'active'),
('60000000-0000-0000-0000-000000000309', '50000000-0000-0000-0000-000000000024', 'expert', 'mcq', 'What is Drift Detection in IaC?', '["Identifying differences between current infrastructure and defined code", "Detecting network speed issues", "Finding unused resources", "Automatic scaling based on load"]', 'Identifying differences between current infrastructure and defined code', 'Drift detection ensures the environment matches the intended state.', 'active'),
('60000000-0000-0000-0000-000000000310', '50000000-0000-0000-0000-000000000024', 'expert', 'mcq', 'What is Pulumi?', '["Infrastructure as Code using general-purpose programming languages", "A type of load balancer", "A cloud-native database", "A firewall service"]', 'Infrastructure as Code using general-purpose programming languages', 'Pulumi supports languages like TypeScript, Python, and Go for IaC.', 'active'),
('60000000-0000-0000-0000-000000000311', '50000000-0000-0000-0000-000000000024', 'expert', 'mcq', 'What is "GitOps"?', '["A way of managing infrastructure using Git as the source of truth", "Managing Git repository permissions", "A new cloud provider", "Automated code commenting"]', 'A way of managing infrastructure using Git as the source of truth', 'GitOps uses Git repos as the single source for declarative infrastructure.', 'active'),
('60000000-0000-0000-0000-000000000312', '50000000-0000-0000-0000-000000000024', 'expert', 'mcq', 'What is the purpose of HCL in Terraform?', '["Human-readable configuration language", "Hyper-speed coding language", "Hidden cloud logic", "Host control level"]', 'Human-readable configuration language', 'HCL is designed to be easy for humans to read and write.', 'active')
