INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000000313', '50000000-0000-0000-0000-000000000025', 'simple', 'mcq', 'What does CIA stand for in Cybersecurity?', '["Confidentiality, Integrity, Availability", "Common Identity Access", "Cyber Integration Agency", "Central Intelligence Access"]', 'Confidentiality, Integrity, Availability', 'The CIA triad is a model designed to guide policies for information security.', 'active'),
('60000000-0000-0000-0000-000000000314', '50000000-0000-0000-0000-000000000025', 'simple', 'mcq', 'What is Confidentiality?', '["Ensuring data is accessible only to authorized users", "Ensuring data is accurate", "Ensuring data is always available", "Ensuring data is encrypted"]', 'Ensuring data is accessible only to authorized users', 'Confidentiality is about hiding information from those not permitted to see it.', 'active'),
('60000000-0000-0000-0000-000000000315', '50000000-0000-0000-0000-000000000025', 'simple', 'mcq', 'What is Integrity?', '["Ensuring data is accurate and unchanged during transit", "Ensuring data is hidden", "Ensuring data is fast", "Ensuring data is deleted"]', 'Ensuring data is accurate and unchanged during transit', 'Integrity involves maintaining consistency, accuracy, and trustworthiness of data.', 'active'),
('60000000-0000-0000-0000-000000000316', '50000000-0000-0000-0000-000000000025', 'simple', 'mcq', 'What is Availability?', '["Ensuring data and resources are accessible when needed", "Ensuring data is private", "Ensuring data is correct", "Ensuring data is encrypted"]', 'Ensuring data and resources are accessible when needed', 'Availability is the guarantee of reliable access to information by authorized people.', 'active'),
('60000000-0000-0000-0000-000000000317', '50000000-0000-0000-0000-000000000025', 'intermediate', 'mcq', 'What is Defense in Depth?', '["Layered security approach", "Single strong firewall", "Encryption only", "Physical security only"]', 'Layered security approach', 'It uses multiple defense layers to protect against various attack vectors.', 'active'),
('60000000-0000-0000-0000-000000000318', '50000000-0000-0000-0000-000000000025', 'intermediate', 'mcq', 'What is Social Engineering?', '["Manipulating people into giving up confidential information", "Hacking a server", "Writing malicious code", "Setting up a firewall"]', 'Manipulating people into giving up confidential information', 'It relies on human interaction and psychological manipulation.', 'active'),
('60000000-0000-0000-0000-000000000319', '50000000-0000-0000-0000-000000000025', 'intermediate', 'mcq', 'What is a "Zero-Day" vulnerability?', '["A vulnerability unknown to the software creator", "A very old vulnerability", "A patched vulnerability", "A vulnerability discovered on a Sunday"]', 'A vulnerability unknown to the software creator', 'Attackers exploit the flaw before the developer has time to fix it.', 'active'),
('60000000-0000-0000-0000-000000000320', '50000000-0000-0000-0000-000000000025', 'intermediate', 'mcq', 'What is Least Privilege?', '["Giving users only the access they need to perform their job", "Giving users full access", "Giving users no access", "Giving only admins access"]', 'Giving users only the access they need to perform their job', 'It limits the potential damage from a security breach.', 'active'),
('60000000-0000-0000-0000-000000000321', '50000000-0000-0000-0000-000000000025', 'expert', 'mcq', 'What is the "Golden Ratio" of security (Policy, Tech, Awareness)?', '["Balanced approach between all three", "Policy is 90% of security", "Awareness is everything", "Technology fixes all problems"]', 'Balanced approach between all three', 'Effective security requires clear policies, technical controls, and user awareness.', 'active'),
('60000000-0000-0000-0000-000000000322', '50000000-0000-0000-0000-000000000025', 'expert', 'mcq', 'What is "Non-repudiation"?', '["Ensuring a party cannot deny an action or message", "Encryption", "Authentication", "Integrity"]', 'Ensuring a party cannot deny an action or message', 'It provides proof of the origin and integrity of data.', 'active'),
('60000000-0000-0000-0000-000000000323', '50000000-0000-0000-0000-000000000025', 'expert', 'mcq', 'What is an "Attack Surface"?', '["The total set of vulnerabilities accessible to an attacker", "The screen of a computer", "The keyboard", "The outward facing firewall only"]', 'The total set of vulnerabilities accessible to an attacker', 'Reducing the attack surface is a key security goal.', 'active'),
('60000000-0000-0000-0000-000000000324', '50000000-0000-0000-0000-000000000025', 'expert', 'mcq', 'What is the "Risk" formula typically used?', '["Risk = Threat x Vulnerability x Asset Value", "Risk = Threat + Vulnerability", "Risk = Cost / Security", "Risk = Attacks - Defenses"]', 'Risk = Threat x Vulnerability x Asset Value', 'This helps prioritize security investments based on potential impact.', 'active'),
('60000000-0000-0000-0000-000000000325', '50000000-0000-0000-0000-000000000025', 'expert', 'mcq', 'What is the difference between an Asset and a Vulnerability?', '["An asset is what you protect; a vulnerability is a weakness in it", "They are the same", "An asset is a hacker", "A vulnerability is a firewall"]', 'An asset is what you protect; a vulnerability is a weakness in it', 'Identification of assets is the first step in risk management.', 'active')
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000000326', '50000000-0000-0000-0000-000000000026', 'simple', 'mcq', 'What is a Firewall?', '["A system designed to block unauthorized access to or from a private network", "A fast internet cable", "A virus scanner", "A physical wall around a server"]', 'A system designed to block unauthorized access to or from a private network', 'Firewalls can be hardware, software, or both.', 'active'),
('60000000-0000-0000-0000-000000000327', '50000000-0000-0000-0000-000000000026', 'simple', 'mcq', 'What is a VPN?', '["Virtual Private Network", "Virtual Public Network", "Visible Private Network", "Virtual Port Node"]', 'Virtual Private Network', 'VPNs create an encrypted tunnel for data transmission.', 'active'),
('60000000-0000-0000-0000-000000000328', '50000000-0000-0000-0000-000000000026', 'simple', 'mcq', 'What is the purpose of an IDS?', '["Intrusion Detection System", "Internet Data Service", "Internal Data Storage", "Identity Detection System"]', 'Intrusion Detection System', 'An IDS monitors network traffic for suspicious activity.', 'active'),
('60000000-0000-0000-0000-000000000329', '50000000-0000-0000-0000-000000000026', 'simple', 'mcq', 'What is Nmap used for?', '["Network scanning and discovery", "Password cracking", "Writing malware", "Deleting logs"]', 'Network scanning and discovery', 'Nmap is a powerful tool for mapping networks and checking open ports.', 'active'),
('60000000-0000-0000-0000-000000000330', '50000000-0000-0000-0000-000000000026', 'intermediate', 'mcq', 'What is the difference between IDS and IPS?', '["IPS can actively block a threat, IDS only alerts", "IDS is faster", "IPS is hardware only", "They are identical"]', 'IPS can actively block a threat, IDS only alerts', 'Intrusion Prevention Systems (IPS) take corrective action.', 'active'),
('60000000-0000-0000-0000-000000000331', '50000000-0000-0000-0000-000000000026', 'intermediate', 'mcq', 'What is a DMZ (Demilitarized Zone)?', '["A sub-network that exposes an organization''s external services to the internet", "A secret server room", "An encrypted folder", "A backup data center"]', 'A sub-network that exposes an organization''s external services to the internet', 'It adds an extra layer of security between the public internet and private network.', 'active'),
('60000000-0000-0000-0000-000000000332', '50000000-0000-0000-0000-000000000026', 'intermediate', 'mcq', 'What is WPA3?', '["The latest Wi-Fi security standard", "A type of firewall", "A VPN protocol", "An encryption algorithm for hard drives"]', 'The latest Wi-Fi security standard', 'WPA3 provides stronger protections for wireless networks compared to WPA2.', 'active'),
('60000000-0000-0000-0000-000000000333', '50000000-0000-0000-0000-000000000026', 'intermediate', 'code_mcq', 'In Nmap, what does the "-sV" flag do?', '["Detects service versions", "Scans ports stealthily", "Performs a fast scan", "Saves output directly"]', 'Detects service versions', 'It attempts to determine the version of the service running on an open port.', 'active'),
('60000000-0000-0000-0000-000000000334', '50000000-0000-0000-0000-000000000026', 'expert', 'mcq', 'What is a Next-Generation Firewall (NGFW)?', '["Includes deep packet inspection and application-level filtering", "A very fast firewall", "A cloud-only firewall", "A virtual firewall"]', 'Includes deep packet inspection and application-level filtering', 'NGFWs go beyond simple port/protocol filtering.', 'active'),
('60000000-0000-0000-0000-000000000335', '50000000-0000-0000-0000-000000000026', 'expert', 'mcq', 'What is BGP Hijacking?', '["Falsely claiming IP prefixes to redirect traffic", "Hacking a router''s password", "Flooding a network with UDP packets", "Stealing certificates"]', 'Falsely claiming IP prefixes to redirect traffic', 'It can lead to data interception or denial of service by diverting internet traffic.', 'active'),
('60000000-0000-0000-0000-000000000336', '50000000-0000-0000-0000-000000000026', 'expert', 'mcq', 'What is "Micro-segmentation"?', '["Granular security at the individual workload level", "Dividing a network into two parts", "Small firewalls for home users", "Reducing packet size"]', 'Granular security at the individual workload level', 'It helps prevent lateral movement of attackers within a data center.', 'active'),
('60000000-0000-0000-0000-000000000337', '50000000-0000-0000-0000-000000000026', 'expert', 'mcq', 'What is "Certificate Pinning"?', '["Associating a host with its expected public key/certificate", "Attaching certificates to a physical wall", "Deleting expired certificates", "Automatically renewing certificates"]', 'Associating a host with its expected public key/certificate', 'It protects against Man-in-the-Middle attacks by verifying the exact certificate.', 'active'),
('60000000-0000-0000-0000-000000000338', '50000000-0000-0000-0000-000000000026', 'expert', 'mcq', 'What is DNSSEC?', '["Suite of specifications for securing DNS information", "A private DNS server", "Encryption for DNS only", "A fast DNS resolver"]', 'Suite of specifications for securing DNS information', 'It provides origin authentication and data integrity to DNS.', 'active')
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000000339', '50000000-0000-0000-0000-000000000027', 'simple', 'mcq', 'What is Ransomware?', '["Malware that encrypts files and demands payment for the decryption key", "Malware that steals passwords", "Malware that deletes data randomly", "Malware that speeds up your computer"]', 'Malware that encrypts files and demands payment for the decryption key', 'Ransomware is a major threat to both individuals and organizations.', 'active'),
('60000000-0000-0000-0000-000000000340', '50000000-0000-0000-0000-000000000027', 'simple', 'mcq', 'What is a Trojan Horse?', '["Malware disguised as legitimate software", "A hardware component", "A type of firewall", "A secure network protocol"]', 'Malware disguised as legitimate software', 'Trojans mislead users of their true intent.', 'active'),
('60000000-0000-0000-0000-000000000341', '50000000-0000-0000-0000-000000000027', 'simple', 'mcq', 'What is Phishing?', '["Fraudulent attempt to obtain sensitive information by masquerading as a trustworthy entity", "A type of malware", "A network scan", "Deleting database records"]', 'Fraudulent attempt to obtain sensitive information by masquerading as a trustworthy entity', 'Phishing is typically conducted via email or instant messaging.', 'active'),
('60000000-0000-0000-0000-000000000342', '50000000-0000-0000-0000-000000000027', 'simple', 'mcq', 'What is a "Botnet"?', '["A network of compromised computers controlled as a group", "A single fast computer", "A type of robot", "A secure database"]', 'A network of compromised computers controlled as a group', 'Botnets are often used for DDoS attacks and spamming.', 'active'),
('60000000-0000-0000-0000-000000000343', '50000000-0000-0000-0000-000000000027', 'intermediate', 'mcq', 'What is a SQL Injection (SQLi) attack?', '["Inserting malicious SQL queries into input fields", "Deleting a database", "Encrypting a database", "Backing up a database"]', 'Inserting malicious SQL queries into input fields', 'SQLi can allow attackers to view, modify, or delete data.', 'active'),
('60000000-0000-0000-0000-000000000344', '50000000-0000-0000-0000-000000000027', 'intermediate', 'mcq', 'What is a Cross-Site Scripting (XSS) attack?', '["Injecting malicious scripts into web pages viewed by other users", "Stealing a server''s password", "Flooding a network with traffic", "Deleting CSS files"]', 'Injecting malicious scripts into web pages viewed by other users', 'XSS can be used to steal cookies or session tokens.', 'active'),
('60000000-0000-0000-0000-000000000345', '50000000-0000-0000-0000-000000000027', 'intermediate', 'mcq', 'What is a Man-in-the-Middle (MitM) attack?', '["Attacker secretly relays and possibly alters communication between two parties", "A loud person in a meeting", "A physical break-in", "A software update"]', 'Attacker secretly relays and possibly alters communication between two parties', 'MitM attacks often occur on unsecured Wi-Fi networks.', 'active'),
('60000000-0000-0000-0000-000000000346', '50000000-0000-0000-0000-000000000027', 'intermediate', 'mcq', 'What is a DDoS attack?', '["Distributed Denial of Service", "Dynamic Data Security", "Distributed Data System", "Direct Denial of Service"]', 'Distributed Denial of Service', 'DDoS uses multiple systems to flood a target''s resources, making it unavailable.', 'active'),
('60000000-0000-0000-0000-000000000347', '50000000-0000-0000-0000-000000000027', 'expert', 'mcq', 'What is "Polymorphic Malware"?', '["Malware that constantly changes its code to evade detection", "Malware that affects multiple files", "Malware that works on multiple OS", "Malware that deletes itself"]', 'Malware that constantly changes its code to evade detection', 'Signature-based antivirus often struggles to detect polymorphic threats.', 'active'),
('60000000-0000-0000-0000-000000000348', '50000000-0000-0000-0000-000000000027', 'expert', 'mcq', 'What is a "Logic Bomb"?', '["Malicious code that triggers upon a specific event or time", "A hard drive failure", "A loud server alarm", "A programming error"]', 'Malicious code that triggers upon a specific event or time', 'Logic bombs are often planted by insiders to execute at a later date.', 'active'),
('60000000-0000-0000-0000-000000000349', '50000000-0000-0000-0000-000000000027', 'expert', 'mcq', 'What is "Credential Stuffing"?', '["Automated injection of stolen username/password pairs", "Writing down passwords", "Guessing a single password", "Deleting old accounts"]', 'Automated injection of stolen username/password pairs', 'It relies on the fact that many users reuse passwords across different sites.', 'active'),
('60000000-0000-0000-0000-000000000350', '50000000-0000-0000-0000-000000000027', 'expert', 'mcq', 'What is a "Rootkit"?', '["Software designed to provide continued privileged access while hiding its presence", "A tool for fixing roots", "A database manager", "A network cable"]', 'Software designed to provide continued privileged access while hiding its presence', 'Rootkits operate at a deep level (often kernel) to remain invisible.', 'active'),
('60000000-0000-0000-0000-000000000351', '50000000-0000-0000-0000-000000000027', 'expert', 'mcq', 'What is "Supply Chain Attack"?', '["Targeting less secure elements in the supply network to reach a primary target", "Stealing from a warehouse", "Hacking a delivery truck", "A type of phising"]', 'Targeting less secure elements in the supply network to reach a primary target', 'Recent high-profile attacks have exploited vulnerabilities in software updates.', 'active')
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000000352', '50000000-0000-0000-0000-000000000028', 'simple', 'mcq', 'What is Penetration Testing (Pentesting)?', '["Authorized simulated cyberattack on a computer system", "Illegal hacking", "A type of firewall", "A network scan only"]', 'Authorized simulated cyberattack on a computer system', 'It helps identify security weaknesses before an attacker can exploit them.', 'active'),
('60000000-0000-0000-0000-000000000353', '50000000-0000-0000-0000-000000000028', 'simple', 'mcq', 'What is a "White Box" test?', '["Pentester has full knowledge of the target system", "Pentester has no knowledge", "Pentester has partial knowledge", "Pentester is a beginner"]', 'Pentester has full knowledge of the target system', 'White box testing provides the most comprehensive view of the system.', 'active'),
('60000000-0000-0000-0000-000000000354', '50000000-0000-0000-0000-000000000028', 'simple', 'mcq', 'What is a "Black Box" test?', '["Pentester has no prior knowledge of the target", "Full knowledge", "Partial knowledge", "Testing a black computer"]', 'Pentester has no prior knowledge of the target', 'It simulates an external attacker with no inside information.', 'active'),
('60000000-0000-0000-0000-000000000355', '50000000-0000-0000-0000-000000000028', 'simple', 'mcq', 'What is a Vulnerability Scanner?', '["Automated tool that checks systems for known security flaws", "A human hacker", "A type of malware", "A secure operating system"]', 'Automated tool that checks systems for known security flaws', 'Examples include Nessus and OpenVAS.', 'active'),
('60000000-0000-0000-0000-000000000356', '50000000-0000-0000-0000-000000000028', 'intermediate', 'mcq', 'What is "Reconnaissance" in pentesting?', '["The discovery and information gathering phase", "The actual hacking phase", "Reporting phase", "Cleaning up traces"]', 'The discovery and information gathering phase', 'It can be passive (browsing websites) or active (scanning ports).', 'active'),
('60000000-0000-0000-0000-000000000357', '50000000-0000-0000-0000-000000000028', 'intermediate', 'mcq', 'What is "Privilege Escalation"?', '["Gaining higher level access than intended", "Updating software", "Logging into a server", "Deleting an account"]', 'Gaining higher level access than intended', 'It can be vertical (user to admin) or horizontal (user to user).', 'active'),
('60000000-0000-0000-0000-000000000358', '50000000-0000-0000-0000-000000000028', 'intermediate', 'mcq', 'What is the CVE system?', '["Common Vulnerabilities and Exposures - a list of publicly disclosed flaws", "A type of encryption", "A security standard", "A cloud provider"]', 'Common Vulnerabilities and Exposures - a list of publicly disclosed flaws', 'Each entry (e.g., CVE-2023-1234) provides a standard identifier for a vulnerability.', 'active'),
('60000000-0000-0000-0000-000000000359', '50000000-0000-0000-0000-000000000028', 'intermediate', 'mcq', 'What is a "Grey Box" test?', '["Partial knowledge of the target", "No knowledge", "Full knowledge", "Testing a grey computer"]', 'Partial knowledge of the target', 'It simulates an insider or an attacker who has gained some access.', 'active'),
('60000000-0000-0000-0000-000000000360', '50000000-0000-0000-0000-000000000028', 'expert', 'mcq', 'What is Metasploit?', '["An exploitation framework for testing vulnerabilities", "A database of passwords", "A Linux distribution", "A secure web browser"]', 'An exploitation framework for testing vulnerabilities', 'Metasploit contains a vast collection of exploits for many vulnerabilities.', 'active'),
('60000000-0000-0000-0000-000000000361', '50000000-0000-0000-0000-000000000028', 'expert', 'mcq', 'What is "Pivoting" in the context of exploitation?', '["Using a compromised system to attack other systems on the same network", "Rotating an encryption key", "Changing the target IP", "Rebooting a server"]', 'Using a compromised system to attack other systems on the same network', 'Pivoting allows attackers to bypass boundary defenses (like firewalls).', 'active'),
('60000000-0000-0000-0000-000000000362', '50000000-0000-0000-0000-000000000028', 'expert', 'mcq', 'What is the difference between VAPT and a single Pentest?', '["VAPT is a continuous/integrated process; Pentest is a point-in-time check", "VAPT is for web apps only", "Pentest is automated only", "VAPT is free"]', 'VAPT is a continuous/integrated process; Pentest is a point-in-time check', 'Vulnerability Assessment and Penetration Testing provide a more holistic security view.', 'active'),
('60000000-0000-0000-0000-000000000363', '50000000-0000-0000-0000-000000000028', 'expert', 'mcq', 'What is "Fuzzing"?', '["Automated software testing that involves providing invalid, unexpected, or random data", "A type of phising", "Encrypting a file", "Scaling a network"]', 'Automated software testing that involves providing invalid, unexpected, or random data', 'Fuzzing helps find bugs and security vulnerabilities related to input handling.', 'active'),
('60000000-0000-0000-0000-000000000364', '50000000-0000-0000-0000-000000000028', 'expert', 'mcq', 'What is CVSS?', '["Common Vulnerability Scoring System", "Cracked Virtual Server System", "Cloud Vulnerability Secure System", "Cyber Verification Standard Score"]', 'Common Vulnerability Scoring System', 'CVSS provides a numerical score to represent the severity of a vulnerability.', 'active')
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000000365', '50000000-0000-0000-0000-000000000029', 'simple', 'mcq', 'What is Encryption?', '["Converting information into a secret code to prevent unauthorized access", "Deleting data", "Compressing data", "Hiding a file"]', 'Converting information into a secret code to prevent unauthorized access', 'Encryption is fundamental to data protection.', 'active'),
('60000000-0000-0000-0000-000000000366', '50000000-0000-0000-0000-000000000029', 'simple', 'mcq', 'What is Symmetric Encryption?', '["Uses the same key for both encryption and decryption", "Uses different keys", "No keys are used", "Uses a public key only"]', 'Uses the same key for both encryption and decryption', 'AES is a popular symmetric encryption algorithm.', 'active'),
('60000000-0000-0000-0000-000000000367', '50000000-0000-0000-0000-000000000029', 'simple', 'mcq', 'What is Asymmetric Encryption (Public Key Cryptography)?', '["Uses a pair of keys (Public and Private)", "Uses one key only", "Uses three keys", "Uses no key"]', 'Uses a pair of keys (Public and Private)', 'RSA is a well-known asymmetric encryption algorithm.', 'active'),
('60000000-0000-0000-0000-000000000368', '50000000-0000-0000-0000-000000000029', 'simple', 'mcq', 'What is Hashing?', '["A one-way function that turns data into a fixed-size string", "A reversible encryption", "A type of database", "A compression method"]', 'A one-way function that turns data into a fixed-size string', 'Hashing is used for integrity checks and password storage.', 'active'),
('60000000-0000-0000-0000-000000000369', '50000000-0000-0000-0000-000000000029', 'intermediate', 'mcq', 'What is AES?', '["Advanced Encryption Standard", "Advanced Electronic System", "Active Encryption Software", "Alpha Electronic Secure"]', 'Advanced Encryption Standard', 'AES is widely used worldwide to protect sensitive data.', 'active'),
('60000000-0000-0000-0000-000000000370', '50000000-0000-0000-0000-000000000029', 'intermediate', 'mcq', 'How do Public and Private keys work together in asymmetric encryption?', '["Public key encrypts; Private key decrypts", "Public key decrypts; Private key encrypts", "Both can do both", "They are identical"]', 'Public key encrypts; Private key decrypts', 'This allows anyone to send secure data to the owner of the private key.', 'active'),
('60000000-0000-0000-0000-000000000371', '50000000-0000-0000-0000-000000000029', 'intermediate', 'mcq', 'What is a "Digital Signature"?', '["A mathematical way to verify authenticity and integrity", "A scanned signature image", "A password", "A type of email"]', 'A mathematical way to verify authenticity and integrity', 'It uses the sender''s private key to sign and public key to verify.', 'active'),
('60000000-0000-0000-0000-000000000372', '50000000-0000-0000-0000-000000000029', 'intermediate', 'mcq', 'What is SHA-256?', '["A popular cryptographic hash function", "An encryption algorithm", "A network protocol", "A virus name"]', 'A popular cryptographic hash function', 'It produces a 256-bit (32-byte) hash value.', 'active'),
('60000000-0000-0000-0000-000000000373', '50000000-0000-0000-0000-000000000029', 'expert', 'mcq', 'What is "Perfect Forward Secrecy" (PFS)?', '["Ensures session keys are not compromised even if the long-term private key is leaked", "Encryption that is unbreakable", "A fast encryption method", "Automatic key rotation"]', 'Ensures session keys are not compromised even if the long-term private key is leaked', 'PFS generates a unique session key for every session.', 'active'),
('60000000-0000-0000-0000-000000000374', '50000000-0000-0000-0000-000000000029', 'expert', 'mcq', 'What is Diffie-Hellman Key Exchange?', '["Method for securely exchanging cryptographic keys over a public channel", "A type of encryption", "A hash function", "A database engine"]', 'Method for securely exchanging cryptographic keys over a public channel', 'It allows two parties to create a shared secret key.', 'active'),
('60000000-0000-0000-0000-000000000375', '50000000-0000-0000-0000-000000000029', 'expert', 'mcq', 'What is a "Salt" in hashing?', '["Random data added to a password before hashing", "A seasoning for computer hardware", "A type of malware", "A redundant server"]', 'Random data added to a password before hashing', 'Salting prevents rainbow table attacks by ensuring unique hashes for same passwords.', 'active'),
('60000000-0000-0000-0000-000000000376', '50000000-0000-0000-0000-000000000029', 'expert', 'mcq', 'What is Elliptic Curve Cryptography (ECC)?', '["Public-key cryptography based on algebraic structure of elliptic curves", "A very old encryption method", "Encryption for circles only", "A hash function variant"]', 'Public-key cryptography based on algebraic structure of elliptic curves', 'ECC provides the same security as RSA/DH with much smaller keys.', 'active'),
('60000000-0000-0000-0000-000000000377', '50000000-0000-0000-0000-000000000029', 'expert', 'mcq', 'What is End-to-End Encryption (E2EE)?', '["Systems where only the communicating users can read the messages", "Servers can read messages", "Encryption during transit only", "Encryption on the hard drive only"]', 'Systems where only the communicating users can read the messages', 'E2EE prevents service providers or middleboxers from accessing content.', 'active')
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000000378', '50000000-0000-0000-0000-000000000030', 'simple', 'mcq', 'What is IAM?', '["Identity and Access Management", "Internal Access Monitor", "Identity Authentication Method", "Integrated Access Module"]', 'Identity and Access Management', 'IAM is a framework of policies and technologies for ensuring the right people have the appropriate access.', 'active'),
('60000000-0000-0000-0000-000000000379', '50000000-0000-0000-0000-000000000030', 'simple', 'mcq', 'What is Multi-Factor Authentication (MFA)?', '["Using two or more verification methods to access a system", "Using many passwords", "Harder to crack passwords", "Using a single safe password"]', 'Using two or more verification methods to access a system', 'MFA adds an extra layer of security beyond just a password.', 'active'),
('60000000-0000-0000-0000-000000000380', '50000000-0000-0000-0000-000000000030', 'simple', 'mcq', 'What is the difference between Authentication and Authorization?', '["AuthN is who you are; AuthZ is what you can do", "They are the same", "AuthN is for admins only", "AuthZ comes before AuthN"]', 'AuthN is who you are; AuthZ is what you can do', 'Authentication verifies identity, while authorization manages permissions.', 'active'),
('60000000-0000-0000-0000-000000000381', '50000000-0000-0000-0000-000000000030', 'simple', 'mcq', 'What is Role-Based Access Control (RBAC)?', '["Assigning permissions based on job roles", "Assigning permissions to individual users only", "No permissions required", "Changing roles every day"]', 'Assigning permissions based on job roles', 'RBAC simplifies management by grouping users with similar needs.', 'active'),
('60000000-0000-0000-0000-000000000382', '50000000-0000-0000-0000-000000000030', 'intermediate', 'mcq', 'What is SSO (Single Sign-On)?', '["Session/user authentication service that permits a user to use one set of login credentials for multiple applications", "One password for one app", "Signing into a computer once a year", "A secure way to delete accounts"]', 'Session/user authentication service that permits a user to use one set of login credentials for multiple applications', 'SSO improves user experience and security management.', 'active'),
('60000000-0000-0000-0000-000000000383', '50000000-0000-0000-0000-000000000030', 'intermediate', 'mcq', 'What is Privilege Access Management (PAM)?', '["Securing and monitoring accounts with elevated permissions", "Managing all guest accounts", "A type of password manager", "Deleting admin users"]', 'Securing and monitoring accounts with elevated permissions', 'PAM is crucial for protecting against internal and external threats to sensitive systems.', 'active'),
('60000000-0000-0000-0000-000000000384', '50000000-0000-0000-0000-000000000030', 'intermediate', 'mcq', 'What is "Attribute-Based Access Control" (ABAC)?', '["Access is granted based on attributes (user, environment, resource)", "Access is based on hair color", "Manual access only", "Database access only"]', 'Access is granted based on attributes (user, environment, resource)', 'ABAC provides more granular control than RBAC.', 'active'),
('60000000-0000-0000-0000-000000000385', '50000000-0000-0000-0000-000000000030', 'intermediate', 'mcq', 'What are "Bio-metrics" in security?', '["Using physical characteristics for identification (fingerprint, face)", "Using a secret code", "Using a physical key card", "Using a complex password"]', 'Using physical characteristics for identification (fingerprint, face)', 'Biometrics provide a high level of identity assurance.', 'active'),
('60000000-0000-0000-0000-000000000386', '50000000-0000-0000-0000-000000000030', 'expert', 'mcq', 'What is OAuth 2.0 primarily used for?', '["Authorization and delegation of access", "Authentication only", "Encrypting databases", "Network scanning"]', 'Authorization and delegation of access', 'It allows a service to access another service on behalf of a user.', 'active'),
('60000000-0000-0000-0000-000000000387', '50000000-0000-0000-0000-000000000030', 'expert', 'mcq', 'What is SAML (Security Assertion Markup Language)?', '["XML-based standard for exchanging authentication and authorization data", "A programming language", "A JSON format only", "A type of firewall configuration"]', 'XML-based standard for exchanging authentication and authorization data', 'SAML is frequently used for web browser-based SSO.', 'active'),
('60000000-0000-0000-0000-000000000388', '50000000-0000-0000-0000-000000000030', 'expert', 'mcq', 'What is an "Identity Provider" (IdP)?', '["System that creates, maintains, and manages identity information", "A user", "A computer monitor", "A password database file only"]', 'System that creates, maintains, and manages identity information', 'Examples include Okta, Azure AD, and Auth0.', 'active'),
('60000000-0000-0000-0000-000000000389', '50000000-0000-0000-0000-000000000030', 'expert', 'mcq', 'What is "Privilege Creep"?', '["Gradual accumulation of access rights beyond what is necessary", "A slow computer", "A hacker entering a network slowly", "Admin account expiration"]', 'Gradual accumulation of access rights beyond what is necessary', 'Regular access reviews are necessary to prevent this.', 'active'),
('60000000-0000-0000-0000-000000000390', '50000000-0000-0000-0000-000000000030', 'expert', 'mcq', 'What is "Just-In-Time" (JIT) provisioning?', '["Granting access for a limited time and only when needed", "Provisioning servers immediately", "Deleting users immediately", "Scaling based on CPU"]', 'Granting access for a limited time and only when needed', 'JIT reduces the risk of long-standing privileges being compromised.', 'active')
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000000391', '50000000-0000-0000-0000-000000000031', 'simple', 'mcq', 'What is "Incident Response" (IR)?', '["Process of reacting to and managing a security breach", "Reporting a lost laptop", "Installing a software update", "Changing a password"]', 'Process of reacting to and managing a security breach', 'An IR plan helps minimize damage and recovery time.', 'active'),
('60000000-0000-0000-0000-000000000392', '50000000-0000-0000-0000-000000000031', 'simple', 'mcq', 'What is "Digital Forensics"?', '["The application of science to identify, collect, and analyze digital evidence", "Watching a crime show", "Deleting browser history", "Building a computer"]', 'The application of science to identify, collect, and analyze digital evidence', 'It is used to investigate cybercrimes and security incidents.', 'active'),
('60000000-0000-0000-0000-000000000393', '50000000-0000-0000-0000-000000000031', 'simple', 'mcq', 'What is the "Chain of Custody"?', '["Documentation showing who handled evidence at every stage", "A physical chain on a server cage", "A sequence of passwords", "A list of attackers"]', 'Documentation showing who handled evidence at every stage', 'Chain of custody is essential for evidence to be admissible in court.', 'active'),
('60000000-0000-0000-0000-000000000394', '50000000-0000-0000-0000-000000000031', 'simple', 'mcq', 'What is an "IoC" (Indicator of Compromise)?', '["Forensic data that suggests a security breach has occurred", "Internal Operation Center", "Identity of the Caller", "Integrated Operation Cloud"]', 'Forensic data that suggests a security breach has occurred', 'Examples include malicious IP addresses or unusual file hashes.', 'active'),
('60000000-0000-0000-0000-000000000395', '50000000-0000-0000-0000-000000000031', 'intermediate', 'mcq', 'What is "Containment" in the incident response lifecycle?', '["Isolating affected systems to prevent further damage", "Deleting the virus", "Reporting to the police", "Ignoring the alert"]', 'Isolating affected systems to prevent further damage', 'It is a crucial step after identification.', 'active'),
('60000000-0000-0000-0000-000000000396', '50000000-0000-0000-0000-000000000031', 'intermediate', 'mcq', 'What does "SIEM" stand for?', '["Security Information and Event Management", "Software Integration and Error Matrix", "System Infrastructure Encryption Module", "Secure Identity Entry Manager"]', 'Security Information and Event Management', 'SIEM provides real-time analysis of security alerts generated by hardware and applications.', 'active'),
('60000000-0000-0000-0000-000000000397', '50000000-0000-0000-0000-000000000031', 'intermediate', 'mcq', 'What is "Log Analysis"?', '["Reviewing records of computer and network activity", "Writing a diary", "Deleting old files", "Checking CPU temperature"]', 'Reviewing records of computer and network activity', 'Log analysis is key to identifying the root cause of an incident.', 'active'),
('60000000-0000-0000-0000-000000000398', '50000000-0000-0000-0000-000000000031', 'intermediate', 'mcq', 'What is a "Sandbox" in forensics/security?', '["Isolated environment for testing suspicious files", "A physical playground", "A slow network", "An encrypted hard drive"]', 'Isolated environment for testing suspicious files', 'Sandboxes prevent malware from affecting the host or network.', 'active'),
('60000000-0000-0000-0000-000000000399', '50000000-0000-0000-0000-000000000031', 'expert', 'mcq', 'What is the "First Responder" rule in digital forensics?', '["Do not alter the original evidence", "Turn off the computer immediately", "Delete suspicious logs", "Run an antivirus scan"]', 'Do not alter the original evidence', 'Preserving the state of the machine is the top priority.', 'active'),
('60000000-0000-0000-0000-000000000400', '50000000-0000-0000-0000-000000000031', 'expert', 'mcq', 'What is "Memory Forensics"?', '["Analyzing volatile data in an organization''s memory (RAM)", "Analyzing old hard drives", "Remembering a password", "Checking server history"]', 'Analyzing volatile data in an organization''s memory (RAM)', 'RAM can contain passwords, decrypted keys, and malware running in memory.', 'active'),
('60000000-0000-0000-0000-000000000401', '50000000-0000-0000-0000-000000000031', 'expert', 'mcq', 'What is a "SOAR" platform?', '["Security Orchestration, Automation, and Response", "Server Overview and Admin Report", "Secure Operating and Access Registry", "System Online and Active Recovery"]', 'Security Orchestration, Automation, and Response', 'SOAR helps automate incident response workflows.', 'active'),
('60000000-0000-0000-0000-000000000402', '50000000-0000-0000-0000-000000000031', 'expert', 'mcq', 'What is "Root Cause Analysis" (RCA)?', '["Method of problem solving used to identify the underlying cause", "Deleting the root user", "Finding where a cable starts", "Updating a server"]', 'Method of problem solving used to identify the underlying cause', 'RCA prevents future recurrence of the same incident.', 'active'),
('60000000-0000-0000-0000-000000000403', '50000000-0000-0000-0000-000000000031', 'expert', 'mcq', 'What is "Data Slack" or "File Slack"?', '["The leftover space in a cluster after a file is written", "A slow network speed", "A type of secure messaging", "The time between two server updates"]', 'The leftover space in a cluster after a file is written', 'It can sometimes contain fragments of previously deleted files.', 'active')
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000000404', '50000000-0000-0000-0000-000000000032', 'simple', 'mcq', 'What is GDPR?', '["General Data Protection Regulation", "Global Data Privacy Role", "Grand Data Protocol Rules", "Government Data Privacy Registry"]', 'General Data Protection Regulation', 'GDPR is a European regulation on data protection and privacy.', 'active'),
('60000000-0000-0000-0000-000000000405', '50000000-0000-0000-0000-000000000032', 'simple', 'mcq', 'What is HIPAA?', '["US law to protect sensitive patient health information", "A type of network port", "A computer part name", "A secure operating system"]', 'US law to protect sensitive patient health information', 'HIPAA is mandatory for healthcare providers in the United States.', 'active'),
('60000000-0000-0000-0000-000000000406', '50000000-0000-0000-0000-000000000032', 'simple', 'mcq', 'What is PCI-DSS?', '["Security standard for organizations that handle credit card data", "Personal Computer Integration", "Public Cloud Infrastructure", "Port Control Interface"]', 'Security standard for organizations that handle credit card data', 'Payment Card Industry Data Security Standard aims to reduce credit card fraud.', 'active'),
('60000000-0000-0000-0000-000000000407', '50000000-0000-0000-0000-000000000032', 'simple', 'mcq', 'What is the purpose of a Security Audit?', '["Systematic evaluation of the security of a company''s information system", "A tax review", "Installing a new firewall", "Updating passwords"]', 'Systematic evaluation of the security of a company''s information system', 'Audits measure how well the organization complies with a set of established criteria.', 'active'),
('60000000-0000-0000-0000-000000000408', '50000000-0000-0000-0000-000000000032', 'intermediate', 'mcq', 'What is a "SOC 2" report?', '["Audit report that provides information about the internal controls of a service organization", "A type of network router", "A password manager update", "A weekly security meeting note"]', 'Audit report that provides information about the internal controls of a service organization', 'SOC 2 is based on Trust Services Criteria: security, availability, processing integrity, confidentiality, and privacy.', 'active'),
('60000000-0000-0000-0000-000000000409', '50000000-0000-0000-0000-000000000032', 'intermediate', 'mcq', 'What is ISO/IEC 27001?', '["International standard for managing information security", "A protocol for cameras", "A type of internet browser", "A hard drive interface standard"]', 'International standard for managing information security', 'It provides a framework for an information security management system (ISMS).', 'active'),
('60000000-0000-0000-0000-000000000410', '50000000-0000-0000-0000-000000000032', 'intermediate', 'mcq', 'What is a "Privacy Policy"?', '["Statement that discloses how a party gathers, uses, and manages a customer''s data", "A law only for government", "A physical wall around a server room", "A secret document for admins only"]', 'Statement that discloses how a party gathers, uses, and manages a customer''s data', 'Most websites are legally required to have a privacy policy.', 'active'),
('60000000-0000-0000-0000-000000000411', '50000000-0000-0000-0000-000000000032', 'intermediate', 'mcq', 'What is NIST?', '["National Institute of Standards and Technology", "Network Information System Tool", "Node Integrated Security Tablet", "New Internet Security Technology"]', 'National Institute of Standards and Technology', 'NIST provides highly respected cybersecurity frameworks (CSF).', 'active'),
('60000000-0000-0000-0000-000000000412', '50000000-0000-0000-0000-000000000032', 'expert', 'mcq', 'What is the "Right to be Forgotten" under GDPR?', '["Data subjects can have their personal data erased", "Right to change passwords", "Right to use a pseudonym", "Right to block ads"]', 'Data subjects can have their personal data erased', 'It is also known as the Right to Erasure.', 'active'),
('60000000-0000-0000-0000-000000000413', '50000000-0000-0000-0000-000000000032', 'expert', 'mcq', 'What is "Privacy by Design"?', '["Integrating privacy into the development of systems from the start", "Designing clear privacy icons", "Only using private servers", "Blocking all cookies by default"]', 'Integrating privacy into the development of systems from the start', 'Privacy becomes a core component of the business process or system.', 'active'),
('60000000-0000-0000-0000-000000000414', '50000000-0000-0000-0000-000000000032', 'expert', 'mcq', 'What is a "DPIA"?', '["Data Protection Impact Assessment", "Digital Privacy Integration Agent", "Database Performance Internal Audit", "Direct Provider Information Access"]', 'Data Protection Impact Assessment', 'It is an important tool for identifying and reducing the privacy risks of projects.', 'active'),
('60000000-0000-0000-0000-000000000415', '50000000-0000-0000-0000-000000000032', 'expert', 'mcq', 'What is FERPA?', '["US law protecting the privacy of student education records", "Federal Emergency Role Platform", "Fast Encryption Reliability Protocol", "File Entry Registry Policy"]', 'US law protecting the privacy of student education records', 'It applies to all schools that receive funds from the US Department of Education.', 'active'),
('60000000-0000-0000-0000-000000000416', '50000000-0000-0000-0000-000000000032', 'expert', 'mcq', 'What is "Compliance Drift"?', '["When an organization falls out of compliance over time as systems change", "Network packet loss", "A hacker moving slowly", "Changing from one law to another"]', 'When an organization falls out of compliance over time as systems change', 'Continuous monitoring is needed to prevent drift.', 'active')
